(window.ARC_DATA = window.ARC_DATA || {}).quests = [{"id":"picking_up_the_pieces","name":{"en":"Picking Up The Pieces","zh":"积少成多"},"desc":{"en":"The storm has mostly settled, but much of our infrastructure has taken a proper beating. If you're hoping to stay with us, I'll need you to pull your weight in the repair efforts.","zh":"风暴已经基本平息，但我们的设施损毁严重。如果你想继续待在这里，就必须为修复工作出一份力。"},"trader":"Shani","objectives":[{"en":"Visit any area on your map with a loot category icon","zh":"访问你地图上带有搜刮类别图标的区域"},{"en":"Loot 3 containers","zh":"搜刮3个容器"}],"rewards":[["rattler_iii",1],["medium_ammo",80]],"next":["clearer_skies","trash_into_treasure"],"depth":1},{"id":"clearer_skies","name":{"en":"Clearer Skies","zh":"清朗天空"},"desc":{"en":"A swarm of disoriented Wasps crashed near one of our skylights.\n\nI need you to help thin ARC's ranks before any more accidents happen, and gather some extra sturdy materials to fix the damage.","zh":"有群迷路的“黄蜂”撞进了我们的一处天窗。\n\n你得帮我削减ARC的数量，以免它们引发更多事故，以及收集一些特别坚固的材料来修复天窗的损坏。"},"trader":"Shani","objectives":[{"en":"Destroy 3 ARC enemies","zh":"摧毁3个ARC敌人"},{"en":"Get 3 ARC Alloy for Shani","zh":"帮萨尼找到3个ARC合金"}],"required":[["arc_alloy",3]],"rewards":[["sterilized_bandage",3],["light_shield",1]],"prev":["picking_up_the_pieces"],"next":["off_the_radar"],"depth":2},{"id":"trash_into_treasure","name":{"en":"Trash Into Treasure","zh":"变废为宝"},"desc":{"en":"There's no such thing as junk, to a Raider; just valuable materials waiting to be recycled.\n\nIf you're going to amount to anything around here, you can't just wait for things to be served on a silver platter.","zh":"奇袭者的字典里没有“垃圾”二字，只有待回收的宝贵材料。\n\n想在这地方混出名堂，天上可不会掉馅饼。"},"trader":"Shani","objectives":[{"en":"Obtain 6 Wires","zh":"获得6根导线"},{"en":"Obtain 1 Battery","zh":"获得1个电池"}],"required":[["wires",6],["battery",1]],"rewards":[["tactical_mk1",1],["adrenaline_shot",3]],"granted":[["binoculars",1]],"prev":["picking_up_the_pieces"],"next":["off_the_radar"],"depth":2},{"id":"off_the_radar","name":{"en":"Off The Radar","zh":"销声匿迹"},"desc":{"en":"The damage down here was pretty bad, but our Topside infrastructure was hit even harder. I still have several antennas that stopped working after the storm.","zh":"下面虽然也一片狼藉，但我们的上层基础设施的情况更不乐观，好几座天线在风暴后就瘫痪了。"},"trader":"Shani","maps":["buried_city","the_spaceport","dam_battlegrounds","riven_tides"],"objectives":[{"en":"Visit a Field Depot","zh":"访问1个前线仓库"},{"en":"Repair the antenna on the roof of the Field Depot","zh":"修理前线仓库屋顶的天线"}],"oneRound":true,"rewards":[["defibrillator",2]],"granted":[["remote_raider_flare",2]],"prev":["clearer_skies","trash_into_treasure"],"next":["a_first_foothold","shoring_up_defenses","battening_down","a_bad_feeling"],"depth":3},{"id":"a_bad_feeling","name":{"en":"A Bad Feeling","zh":"不祥预感"},"desc":{"en":"Even the slightest change to ARC's behavior could spell disaster.\n\nAnd that signal you heard? It's like nothing we've ever picked up. If they're up to something, we need to find out whatever we can.","zh":"即使ARC行为最微小的改变也可能意味着灾难。\n\n你听到的那个信号，跟我们以前接收到的任何信号都不同。如果它们有什么企图，我们必须尽可能调查清楚。"},"trader":"Celeste","objectives":[{"en":"Find and search any ARC Probe or ARC Courier","zh":"找到并搜索ARC探测器或ARC运输机"}],"rewards":[["metal_parts",10],["steel_spring",5],["duct_tape",5]],"prev":["off_the_radar"],"next":["in_my_image","safe_passage","the_right_tool","hatch_repairs"],"depth":4},{"id":"a_first_foothold","name":{"en":"A First Foothold","zh":"首个立足点"},"desc":{"en":"We’ve only just finished expanding the Tube network towards the Blue Gate, and we’re still laboring away at the rest.\n\nMy crew’s been building new infrastructure around the valley to safeguard our Raiders, but the constant ARC threat has made it difficult to get anything done.","zh":"我们刚把暗道网络扩展到蓝门附近，其他路段还在加紧施工。我的小队正在山谷周边修建新基础设施来保护奇袭者，但ARC持续不断的威胁让工程举步维艰。"},"trader":"Apollo","maps":["the_blue_gate"],"objectives":[{"en":"Stabilize the observation deck near the Ridgeline","zh":"稳定山脊线附近的观测台"},{"en":"Enable the comms terminal near the Olive Grove","zh":"启动橄榄树林附近的通讯终端"},{"en":"Rotate the satellite dishes on the church roof, north of the Data Vault","zh":"转动数据仓库北边教堂屋顶的卫星天线"},{"en":"Nail down the roof plates on the Raider structure near Trapper's Glade","zh":"固定猎人林地附近奇袭者建筑屋顶的钢板"}],"rewards":[["shrapnel_grenade",3],["snap_blast_grenade",3],["heavy_fuze_grenade",3]],"granted":[["noisemaker",2]],"other":[{"en":"18x Raids","zh":"18 局"}],"prev":["off_the_radar"],"next":["reduced_to_rubble"],"depth":4},{"id":"battening_down","name":{"en":"Battening Down","zh":"加固防御"},"desc":{"en":"We’d hoped the seawalls at Riven Tides might offer us some protection from the elements, but it seems the hurricanes were not kind to this place, either.","zh":"我们本指望裂潮镇的海堤能抵御天灾，可飓风也没放过这里。"},"trader":"Apollo","maps":["riven_tides"],"objectives":[{"en":"Photograph the cracks forming in the seawall","zh":"拍摄海堤上的裂缝"},{"en":"Sample the shoreline near the hotel beach","zh":"在酒店海滩附近的海岸线采集样本"},{"en":"Fix the leaking oil pipe in the northeast","zh":"修复东北部的漏油管道"}],"rewards":[["riven_tides_hotel_keycard_no_107",1],["smoke_grenade_trap",3]],"other":[{"en":"20x Raids","zh":"20 局"}],"prev":["off_the_radar"],"depth":4},{"id":"shoring_up_defenses","name":{"en":"Shoring Up Defenses","zh":"加固海岸防线"},"desc":{"en":"The wide-open coastline used to mean danger, but now it's the only place we can spot new threats moving into the Rust Belt.\n\nSo we'll have to make our own cover, and reinforce what few defenses we can find.","zh":"过去，开阔的海岸线曾是危险的象征；但现在，这里是我们唯一能发现威胁侵入锈带的地方。\n\n所以我们得自己搭建掩体，加固仅存的防御工事。"},"trader":"Apollo","maps":["riven_tides"],"objectives":[{"en":"Destroy 5 Wasps","zh":"摧毁5个“黄蜂”"},{"en":"Destroy 3 Fireflies","zh":"摧毁3个“萤火虫”"},{"en":"Use 1 ARC Alloy to reinforce the Raider structure on top of any Stacking Yard crane","zh":"使用1块ARC合金，加固任意堆料场起重机顶部的奇袭者建筑"},{"en":"Board up shuttered windows in the hotel","zh":"用木板封住酒店的百叶窗"}],"rewards":[["barricade_kit",3],["lure_grenade_trap",3],["seeker_grenade",6]],"granted":[["dockmasters_detector",1]],"other":[{"en":"20x Raids","zh":"20 局"}],"prev":["off_the_radar"],"depth":4},{"id":"hatch_repairs","name":{"en":"Hatch Repairs","zh":"暗门维修"},"desc":{"en":"Our scouts have reported several Raider Hatches with leaking hydraulic pipes. They still work, but not for long. Mind patching one up, next time you’re out there?","zh":"我们的侦察者报告说，有几个奇袭者暗门的液压管漏水了。虽然还能用，但撑不了多久。下次外出的时候，能不能去补好其中一个？"},"trader":"Shani","objectives":[{"en":"Repair the leaking hydraulic pipes near a Raider Hatch","zh":"修理奇袭者暗门附近泄漏的液压管"},{"en":"Search for a Hatch Key near the Raider Hatch","zh":"在奇袭者暗门附近寻找暗门钥匙"}],"rewards":[["raider_hatch_key",1],["binoculars",1]],"prev":["a_bad_feeling"],"next":["down_to_earth"],"depth":5},{"id":"in_my_image","name":{"en":"In My Image","zh":"与我同“形”"},"desc":{"en":"I just treated one of the first Raiders who visited Stella Montis, and she said that she saw... others. Androids, very much like me.","zh":"我刚治疗了一位首批进入星辰山的奇袭者，她说她看到了其他的……人形机器人，非常像我的那种。"},"trader":"Lance","maps":["stella_montis"],"objectives":[{"en":"Deploy into Stella Montis","zh":"部署到星辰山"},{"en":"Find and search 3 Androids","zh":"找到并搜索3个人形机器人"}],"rewards":[["looting_mk2",1],["green_light_stick",5]],"granted":[["defibrillator",3]],"other":[{"en":"24x Raids","zh":"24 局"}],"prev":["a_bad_feeling"],"next":["cold_storage"],"depth":5},{"id":"reduced_to_rubble","name":{"en":"Reduced to Rubble","zh":"化为废墟"},"desc":{"en":"That collapsed highway worries me; it looks to be recent. Much of Topside may be in ruins, but most of it is from ages ago.","zh":"那段坍塌的高速让我有点担心。看起来是最近才发生的事。上层大部分地区可能已经变成废墟，但大多是很久以前的事了。"},"trader":"Shani","maps":["the_blue_gate"],"objectives":[{"en":"Take a photo of the Collapsed Highway","zh":"拍摄崩塌高速公路的照片"},{"en":"Go to the Broken Earth","zh":"前往破碎地貌"},{"en":"Follow the trail of destruction through the Broken Earth","zh":"沿着破碎地貌中的毁灭之迹调查"},{"en":"Investigate the unknown ARC machines","zh":"调查未知的ARC机器"}],"rewards":[["zipline",1],["barricade_kit",3],["door_blocker",3]],"granted":[["binoculars",1]],"prev":["a_first_foothold"],"next":["with_a_trace"],"depth":5},{"id":"safe_passage","name":{"en":"Safe Passage","zh":"安全通路"},"desc":{"en":"I heard rumors about some signal Shani picked up. ARC is constantly adapting, and I'm sure this won’t be their last warning sign.\n\nWell, if it’s an arms race they want, they can get one.","zh":"我听说萨尼捕捉到一些奇怪的信号。看来ARC在不断适应，这应该不是它们最后的警告信号。\n\n好吧，如果它们想要来一场军备竞赛，那我们就满足它们。"},"trader":"Apollo","objectives":[{"en":"Destroy 2 ARC enemies using any explosive grenade","zh":"使用任意爆炸式手雷摧毁2个ARC敌人"}],"rewards":[["lil_smoke_grenade",5],["shrapnel_grenade",3],["barricade_kit",3]],"granted":[["light_impact_grenade",5],["light_impact_grenade",5],["snap_blast_grenade",3]],"prev":["a_bad_feeling"],"next":["what_goes_around","collision_course"],"depth":5},{"id":"the_right_tool","name":{"en":"The Right Tool","zh":"正确工具"},"desc":{"en":"You're one of the new arrivals, right? I need a volunteer to test out this upgraded Ferro; should cut through ARC plating like butter. Go put holes in some machines, and report back to me.","zh":"你是新来的吧？我需要个志愿者去测试这个升级版的生铁，它应该可以轻松打穿ARC的装甲。去对着机器打几枪，把结果告诉我。"},"trader":"Tian Wen","objectives":[{"en":"Destroy a Fireball","zh":"摧毁一个“火球”"},{"en":"Destroy a Hornet","zh":"摧毁一架“马蜂”"},{"en":"Destroy a Turret","zh":"摧毁一个炮塔"}],"rewards":[["stitcher_ii",1],["extended_light_mag_i",1]],"granted":[["ferro_iv",1],["heavy_ammo",20]],"prev":["a_bad_feeling"],"next":["a_better_use"],"depth":5},{"id":"a_better_use","name":{"en":"A Better Use","zh":"更好的用途"},"desc":{"en":"We're short on everything but mouths to feed, yet Celeste's launching precious supplies into the air for Raiders to claw over. I’m done letting the good stuff go to waste.","zh":"除了不缺吃饭的嘴巴，我们啥都缺。但是塞莱斯特依然把宝贵的补给发到上头去给奇袭者使用。好东西就这样浪费，我忍不了。"},"trader":"Tian Wen","maps":["buried_city","the_spaceport","the_blue_gate","dam_battlegrounds","riven_tides"],"objectives":[{"en":"Request in a Supply Drop from a Call Station","zh":"在补给呼叫站请求补给"},{"en":"Loot a Supply Drop","zh":"搜刮一个补给投放点"}],"rewards":[["extended_light_mag_i",1],["stable_stock_i",1],["muzzle_brake_ii",1]],"prev":["the_right_tool"],"next":["greasing_her_palms"],"depth":6},{"id":"cold_storage","name":{"en":"Cold Storage","zh":"冷冻储藏"},"desc":{"en":"Reports about Stella Montis keep coming in, and it’s unlike anything we’ve seen before. There may be records or relics from the past in there, and if so, I want them.","zh":"最近不断收到有关于星辰山的报告，那里跟我们之前见过的任何地方都不一样。里面可能存有过去的记录或遗物，如果有的话，我要。"},"trader":"Shani","maps":["stella_montis"],"objectives":[{"en":"Search any J Kozma Ventures container","zh":"搜刮任意J·科兹马创投公司的容器"},{"en":"Deliver the Old World Books to Shani","zh":"将旧世界书籍交给萨尼"}],"oneRound":true,"required":[["old_world_books",1]],"rewards":[["gas_mine",3],["raider_hatch_key",1]],"prev":["in_my_image"],"next":["snap_and_salvage"],"depth":6},{"id":"collision_course","name":{"en":"Collision Course","zh":"碰撞航线"},"desc":{"en":"Many Raiders have learned how to dodge a Comet, but far too few know how to bring them down and get at their inner parts.","zh":"不少奇袭者都懂得如何躲避“彗星”，可没几个人知道怎么击落它、拆出内部零件。"},"trader":"Tian Wen","objectives":[{"en":"Destroy a Comet","zh":"摧毁一个“彗星”"},{"en":"Deliver a Comet Igniter to Tian Wen","zh":"将“彗星”点火器交给天玟"}],"required":[["comet_igniter",1]],"rewards":[["canto_i",1],["extended_medium_mag_iii",1],["muzzle_brake_ii",1]],"prev":["safe_passage"],"depth":6},{"id":"down_to_earth","name":{"en":"Down to Earth","zh":"踏实补给"},"desc":{"en":"Raiders have long reported peculiar-looking crates dropping down from malfunctioning ARC Probes. \n\nIf we can figure out a way to crack them open, we might get a better understanding of what it is they’re after.","zh":"一直以来有奇袭者报告说，出故障的ARC探测器会空投外表奇特的箱子。如果能撬开这种箱子，或许能摸清它们的目的。"},"trader":"Shani","maps":["buried_city","the_spaceport","dam_battlegrounds","riven_tides"],"objectives":[{"en":"Visit a Field Depot","zh":"访问1个前线仓库"},{"en":"Deliver a Field Crate to a Field Depot","zh":"将箱子交付至前线仓库"},{"en":"Collect the reward","zh":"领取奖励"}],"oneRound":true,"rewards":[["combat_mk1",1],["medium_shield",1]],"granted":[["binoculars",1]],"prev":["hatch_repairs"],"next":["the_trifecta"],"depth":6},{"id":"what_goes_around","name":{"en":"What Goes Around","zh":"因果报应"},"desc":{"en":"We can't build ARC tech from scratch, but there's plenty I can tinker from the pieces you salvage.\n\nI'm currently trying to repurpose different ARC parts. Would you mind running some experiments for me?","zh":"我们没办法从零开始打造出ARC技术，但你回收的零件可以大量利用。\n\n目前我正在尝试改装各种ARC零件。能不能帮我开展一些实验？"},"trader":"Apollo","objectives":[{"en":"Destroy any ARC enemy using a Fireball Burner","zh":"使用“火球”燃烧炉摧毁任意ARC敌人"}],"rewards":[["blaze_grenade",3],["noisemaker",2]],"granted":[["red_light_stick",5]],"prev":["safe_passage"],"next":["sparks_fly"],"depth":6},{"id":"with_a_trace","name":{"en":"With A Trace","zh":"蛛丝马迹"},"desc":{"en":"That downed machine… We weren’t the ones who did that. We know that there are stray survivors out there, but this? This goes far beyond a single person.","zh":"那台被击落的机器……不是我们干的。我们知道外面有零星流浪的幸存者，但这件事情……远远不是一个人能做到的。"},"trader":"Shani","maps":["the_blue_gate"],"objectives":[{"en":"Reach the Barren Clearing","zh":"抵达荒芜空地"},{"en":"Find signs of who brought down the ARC machines","zh":"寻找能查清是谁击落ARC机器的线索"},{"en":"Inspect the Adorned Wreckage","zh":"检查庄严残骸"},{"en":"Inspect the communications device","zh":"检查通讯设备"}],"rewards":[["looting_mk2",1],["medium_shield",1]],"prev":["reduced_to_rubble"],"next":["armored_transports","the_clean_dream"],"depth":6},{"id":"greasing_her_palms","name":{"en":"Greasing Her Palms","zh":"打通通路"},"desc":{"en":"Recently, I’ve been trying and failing to get Tian Wen to join our community projects.\n\nI may have to sweeten the deal. She’s been complaining about the quality of salvage found on the market; think we could do her a solid?","zh":"最近我一直想拉天玟加入我们的社区项目，但没成功。我可能得让她先得点甜头了。她一直吐槽市场上回收物品的质量。能不能以此为切入点，帮她个忙？"},"trader":"Celeste","maps":["buried_city","the_spaceport","dam_battlegrounds"],"objectives":[{"en":"On Dam Battlegrounds, visit the Locked Room in the Water Treatment Control building","zh":"在大坝战场，前往水处理控制大楼的上锁房间"},{"en":"On Spaceport, scope out the rocket thrusters outside the Rocket Assembly","zh":"在太空港，侦察火箭组装区外的火箭推进器"},{"en":"On Buried City, visit the barricaded area on floor 6 of the Space Travel Building","zh":"在掩埋废城，前往航天大楼6层的封锁区域"},{"en":"Find a spare Dam Surveillance Key","zh":"找到备用的大坝监控室钥匙"}],"rewards":[["lure_grenade_blueprint",1],["speaker_component",3],["electrical_components",3]],"granted":[["dam_surveillance_key",2]],"prev":["a_better_use"],"next":["dormant_barons","doctors_orders"],"depth":7},{"id":"snap_and_salvage","name":{"en":"Snap and Salvage","zh":"拍照并拆解回收"},"desc":{"en":"All of Speranza is buzzing about Stella Montis right now, and I admit it’s caught my attention. Let the others sort out the whats and hows; I’m interested in the tech inside.","zh":"现在整个斯佩兰扎都在热议星辰山，我承认这也引起了我的注意。让其他人去搞清楚它的来龙去脉好了，我感兴趣的是里面的科技。"},"trader":"Tian Wen","maps":["stella_montis"],"objectives":[{"en":"Take a Photo of any of the Rovers in the Sandbox","zh":"拍摄沙盘中任意探测车的照片"},{"en":"Search the papers in the Security Checkpoint room by the Lobby","zh":"在大厅的安全检查站中寻找文件"},{"en":"Deliver a Magnetron to Tian Wen","zh":"将磁控管交给天玟"},{"en":"Deliver a Flow Controller to Tian Wen","zh":"将流量控制器交给天玟"}],"required":[["magnetron",1],["flow_controller",1]],"rewards":[["burletta_iii",1],["silencer_ii",1],["extended_light_mag_ii",1],["light_ammo",100]],"prev":["cold_storage"],"next":["on_deaf_ears","with_a_view"],"depth":7},{"id":"sparks_fly","name":{"en":"Sparks Fly","zh":"灭蜂大计"},"desc":{"en":"Those Hornet stings can really mess you up, if you’re unlucky. And even if you destroy one, you’re still wasting a ton of ammo.\n\nI’ve been working on a more elegant way to bring them down. Care to make some sparks fly?","zh":"运气不好的话，那些“马蜂”够你喝一壶的。就算运气好能摧毁一架，也要浪费一大堆弹药。\n\n我一直在研究更优雅的方法来干掉它们。能不能帮我验证一下？"},"trader":"Apollo","objectives":[{"en":"Destroy a Hornet with a Trigger 'Nade or Snap Blast","zh":"用触发式手雷或闪爆手雷摧毁1架“马蜂”"}],"rewards":[["trigger_nade_blueprint",1],["crude_explosives",4],["processor",2]],"granted":[["trigger_nade",3],["trigger_nade",3],["snap_blast_grenade",2]],"prev":["what_goes_around"],"next":["the_league","out_of_the_shadows"],"depth":7},{"id":"the_clean_dream","name":{"en":"The Clean Dream","zh":"净梦计划"},"desc":{"en":"You know what I've been dreaming of lately? A talking water distiller! Crazy, huh? But seriously, with purer compounds I could make explosives with more oumph! Would be something, right?","zh":"知道我最近梦到什么吗？会说话的水蒸馏器！这就离谱。但说真的，如果有更纯净的化合物，我就能造出更带劲的炸药！够意思吧？"},"trader":"Apollo","maps":["the_spaceport","the_blue_gate"],"objectives":[{"en":"On Spaceport, search 4 containers in the underground tunnels","zh":"在太空港下方的隧道中搜索4个容器"},{"en":"Find and monitor any Filtration System in the tunnels","zh":"在隧道中寻找并监测任何过滤系统"},{"en":"On The Blue Gate, visit the Maintenance Bunker","zh":"在蓝门找到维护区地堡"},{"en":"Monitor the Purification System in the bunker","zh":"监测地堡中的净化系统"},{"en":"Find and photograph the blueprints in the bunker","zh":"在地堡中找到并拍摄蓝图"}],"rewards":[["deadline",2],["showstopper",3],["heavy_fuze_grenade",3]],"granted":[["blue_light_stick",5]],"prev":["with_a_trace"],"next":["keeping_an_eye_out","outstanding_balance","a_prime_specimen"],"depth":7},{"id":"the_trifecta","name":{"en":"The Trifecta","zh":"三连胜"},"desc":{"en":"Intel’s all well and good, but it only gets us so far. If ARC’s truly closing in, I need every Raider to prove they can handle their drones in a fight.","zh":"情报很有用，但还远远不够。如果ARC真的全线压过来了，每个奇袭者都得证明自己能硬刚无人机。"},"trader":"Shani","maps":["buried_city","the_spaceport","the_blue_gate","dam_battlegrounds"],"objectives":[{"en":"Destroy a Wasp","zh":"摧毁一架“黄蜂”"},{"en":"Get a Wasp Driver for Shani","zh":"帮萨尼获得一个“黄蜂”引擎"},{"en":"Destroy a Hornet","zh":"摧毁一架“马蜂”"},{"en":"Get a Hornet Driver for Shani","zh":"帮萨尼获得一个“马蜂”引擎"},{"en":"Destroy a Snitch","zh":"摧毁1个“告密者”"},{"en":"Get a Snitch Scanner for Shani","zh":"帮萨尼找到一个“告密者”扫描仪"}],"required":[["wasp_driver",2],["hornet_driver",2],["snitch_scanner",2]],"rewards":[["raider_hatch_key",1],["defibrillator",2],["dam_control_tower_key",1]],"granted":[["remote_raider_flare",3]],"prev":["down_to_earth"],"next":["dormant_barons","dust_on_the_wires"],"depth":7},{"id":"a_prime_specimen","name":{"en":"A Prime Specimen","zh":"完美样本"},"desc":{"en":"That Deforester by the Blue Gate may have caused some real devastation, but a pristine husk like that is also an invaluable sample for our research.","zh":"蓝门旁边的那个“伐木手”造成了不少的破坏，但那样完好的残骸也是我们研究中的无价样本。"},"trader":"Shani","maps":["the_blue_gate"],"objectives":[{"en":"Obtain 2 ARC Powercells","zh":"获得2个ARC能量电池"},{"en":"Interact with any ARC Deforester","zh":"与任意ARC“伐木手”互动"},{"en":"Loot an ARC Deforester","zh":"搜刮一个ARC“伐木手”"}],"oneRound":true,"required":[["arc_powercell",2]],"rewards":[["patrol_car_key",1],["door_blocker",3]],"granted":[["remote_raider_flare",3]],"prev":["the_clean_dream"],"depth":8},{"id":"doctors_orders","name":{"en":"Doctor's Orders","zh":"医生的订单"},"desc":{"en":"Say, newbie: if you want me to treat you, you better prove that those precious limbs of yours are worth bandaging.","zh":"新来的，规矩是这样的：如果想让我替你治疗，最好证明一下你那宝贵的四肢值得我包扎。"},"trader":"Lance","objectives":[{"en":"Obtain 1 Syringe","zh":"获得1支注射器"},{"en":"Obtain 2 Antiseptic","zh":"获得2份防腐剂"},{"en":"Obtain 1 Durable Cloth","zh":"获得1块耐磨布料"},{"en":"Obtain 1 Great Mullein","zh":"获得1个大毛蕊花"}],"required":[["syringe",1],["antiseptic",2],["durable_cloth",1],["great_mullein",1]],"rewards":[["adrenaline_shot",3],["sterilized_bandage",3],["surge_shield_recharger",1]],"prev":["greasing_her_palms"],"next":["medical_merchandise"],"depth":8},{"id":"dormant_barons","name":{"en":"Dormant Barons","zh":"休眠的“男爵”"},"desc":{"en":"During the First Wave, the Barons did more damage than all the other machines combined. Now they’re mere husks; fixed in place where they once fell... \n\nStill, their internals might hold the answer to keeping ARC at bay. So open one up, and bring me whatever is inside.","zh":"在“第一波”攻击中，“男爵”比其他所有机器加起来都更具破坏力。如今它们已经成了无用的空壳，倒在那里后就再没有被挪动过……不过，它们内部可能藏着抵御ARC的解决方案。去找一个撬开，把里面的东西带给我。"},"trader":"Shani","maps":["the_spaceport","the_blue_gate","dam_battlegrounds"],"objectives":[{"en":"Loot a Baron husk","zh":"搜刮一个“男爵”残骸"}],"rewards":[["door_blocker",3],["lil_smoke_grenade",3]],"prev":["greasing_her_palms","the_trifecta"],"next":["mixed_signals","clamoring_for_attention","what_we_left_behind"],"depth":8},{"id":"dust_on_the_wires","name":{"en":"Dust on the Wires","zh":"线路积尘"},"desc":{"en":"I sent a scout team to the Spaceport a while ago. Routine work — cataloging security, see if there's anything we could re-purpose. But I've heard nothing for two days.","zh":"不久前我派了一支侦察队去太空港，执行常规任务，就是登记安保设施，看看有无可再利用的设备。但已经两天没有收到他们的消息了。"},"trader":"Shani","maps":["the_spaceport"],"objectives":[{"en":"Visit any Field Depot on the eastern side of the Spaceport","zh":"访问太空港东侧的任意前线仓库"},{"en":"Use the Field Radio to transmit the scout group’s last log to Shani","zh":"使用野外电台将侦察队的最后日志发送给萨尼"},{"en":"Interact with the terminal in the old Raider Tower north of the Maintenance Hangar","zh":"与维护区机库北侧旧奇袭者塔楼中的终端互动"},{"en":"Find traces of the scout patrol near the Maintenance Hangar","zh":"在维护区机库附近寻找侦察队的踪迹"},{"en":"Search the remains left by the scouts","zh":"搜查侦察员留下的遗物"},{"en":"Deliver the Scout Patrol Note to Shani","zh":"将侦察巡逻笔记交给萨尼"}],"oneRound":true,"required":[["scout_patrol_note",1]],"prev":["the_trifecta"],"next":["waking_the_grid","fragmented_logs"],"depth":8},{"id":"keeping_an_eye_out","name":{"en":"Keeping an Eye Out","zh":"循“目”追踪"},"desc":{"en":"I’m looking for someone. Bilguun. You might’ve seen him around, but chances are you haven’t. He’s… not the most sociable person around, you see.\n\nHe spends a lot of time Topside, but usually returns to Speranza regularly to check in.","zh":"我在找一个名叫比尔根的人。你可能见过他，但多半没有。他这人……不怎么爱交际。\n\n大部分时间都在上层，但通常会定期返回斯佩兰扎露个脸。"},"trader":"Celeste","maps":["the_blue_gate"],"objectives":[{"en":"Locate the collapsed highway by the southern edge of the Barren Clearing","zh":"在荒芜空地南部边缘找到坍塌的高速公路"},{"en":"Find Bilguun's shelter, and search for any clues of his presence","zh":"找到比尔根的庇护所，并搜寻有关他下落的线索"}],"rewards":[["pulse_mine",5],["flame_spray",1]],"prev":["the_clean_dream"],"depth":8},{"id":"outstanding_balance","name":{"en":"Outstanding Balance","zh":"未结债务"},"desc":{"en":"I had a deal for a Bastion Cell lined up with a Raider called Dodger, but he's gone quiet. \n\nI need someone to track down his stash before some scavenger stumbles into it. Interested?","zh":"我和一个叫道奇的奇袭者约好交易一个“堡垒”电池，可他突然失联了。\n\n我需要有人帮忙追回他的储备箱，避免落入拾荒者之手。有兴趣吗？"},"trader":"Tian Wen","maps":["the_blue_gate"],"objectives":[{"en":"Search for Dodger's stash inside the Traffic Tunnel","zh":"在通行隧道内寻找道奇的储备箱"},{"en":"Search Dodger's deal spot by the Pilgrim's Peak antenna","zh":"搜查朝圣峰天线附近道奇的交易地点"},{"en":"Deliver Dodger's Note to Tian Wen","zh":"将道奇的笔记交给天玟"}],"oneRound":true,"required":[["dodgers_note",1]],"rewards":[["extended_medium_mag_iii",1],["silencer_ii",1]],"prev":["the_clean_dream"],"next":["settled_in_full"],"depth":8},{"id":"the_league","name":{"en":"The League","zh":"球队"},"desc":{"en":"Kids around here have been kicking empty grenade casings around. It’s only a matter of time before they’re not so empty.\n\nSo here’s the plan. You help me with some prep work, and I’ll set up an actual football team for the young ones.","zh":"这儿的孩子们一直在踢空的榴弹壳玩。这样下去，迟早会踢到有火药剩下的弹壳。所以我们要这样做：你帮我做些准备工作，我给小家伙们组建一支真正的足球队。"},"trader":"Apollo","maps":["dam_battlegrounds","buried_city"],"objectives":[{"en":"Deliver a Deflated Football to Apollo","zh":"将泄气的足球交给阿波罗"},{"en":"Deliver a Bicycle Pump to Apollo","zh":"将一个自行车打气筒交给阿波罗"},{"en":"On Dam Battlegrounds, photograph the goal by the Water Towers","zh":"在大坝战场拍摄水塔旁边的球门"},{"en":"On Buried City, photograph the football magazines in any kiosk","zh":"在掩埋废城拍摄任意报刊亭里的足球杂志"},{"en":"Search for a Deflated Football","zh":"寻找一个瘪掉的足球"},{"en":"Search for a Bicycle Pump","zh":"寻找自行车气筒"}],"required":[["deflated_football",1],["bicycle_pump",1]],"rewards":[["tagging_grenade",5],["firecracker",5]],"granted":[["yellow_light_stick",5],["red_light_stick",5]],"prev":["sparks_fly"],"next":["test_case"],"depth":8},{"id":"with_a_view","name":{"en":"With a View","zh":"风景如画"},"desc":{"en":"Have you ever noticed those streaks of light darting across the skies? \n\nI’ve seen too much to believe they’re natural, but it’ll take more than a hunch to convince Celeste.","zh":"有没有注意过那些划过天际的流光？\n\n我见过太多，已经无法相信它们是自然现象，但要说服塞莱斯特，仅凭直觉可不够。"},"trader":"Shani","maps":["stella_montis"],"objectives":[{"en":"Obtain a Rotary Encoder","zh":"获得一个旋转编码器"},{"en":"Visit any of the Control Rooms near the Assembly Line","zh":"前往组装厂装配线附近的任意控制室"},{"en":"Use the Rotary Encoder to activate the server switch","zh":"使用旋转编码器启动服务器开关"},{"en":"Interact with a nearby computer to help identify the correct parts","zh":"与附近的电脑互动以识别正确的部件"},{"en":"Deliver an Ion Sputter to Shani","zh":"将一台离子溅射仪交给萨尼"}],"required":[["rotary_encoder",1],["ion_sputter",1]],"rewards":[["steel_spring",5],["wires",5],["tactical_mk2",1]],"prev":["snap_and_salvage"],"next":["stable_housing","movie_night"],"depth":8},{"id":"clamoring_for_attention","name":{"en":"Clamoring for Attention","zh":"哗众取宠"},"desc":{"en":"I think I've found something we might exploit. When bigger ARC machines are just far enough from each other, a well-timed distraction could pull one out of position. You want to test that idea?","zh":"我发现了一个可利用的点。当大型ARC机器彼此距离足够远时，一次恰到好处的干扰就能让其中一台脱离站位。想测试这个想法吗？"},"trader":"Shani","maps":["the_blue_gate"],"objectives":[{"en":"Use 3 Wires to repair and sound the emergency siren by the Warehouse Complex","zh":"使用3根导线修复并鸣响仓储综合区旁的紧急警报器"},{"en":"Use a Battery to start the boom box in the Village","zh":"使用电池启动村庄内的音响"},{"en":"Sound any bus horn by the Checkpoint","zh":"鸣响检查站旁的任意巴士喇叭"}],"rewards":[["lure_grenade",5],["noisemaker",5],["tagging_grenade",3]],"other":[{"en":"18x Raids","zh":"18 局"}],"prev":["dormant_barons"],"depth":9},{"id":"medical_merchandise","name":{"en":"Medical Merchandise","zh":"医疗物资"},"desc":{"en":"I’ve become quite crafty at weaving bandages from Fabric, but to my shame, I haven’t quite mastered weaving an x-ray machine or a pulse oximiter.","zh":"我用布料编织绷带是一把好手……但X光机和血氧仪我可整不出来。"},"trader":"Lance","maps":["buried_city","the_spaceport","dam_battlegrounds"],"objectives":[{"en":"On Spaceport, search 2 containers in the Departure Building's exam rooms","zh":"在太空港候机楼的体检室中搜索2个容器"},{"en":"Search 3 containers in the Hospital in Buried City","zh":"在掩埋废城的医院搜索3个容器"},{"en":"On Dam Battlegrounds, search 2 containers in the Research & Administration building's medical room","zh":"在大坝战场的研究与行政区大楼的医疗室搜索2个容器"}],"rewards":[["defibrillator",3],["vita_shot",2]],"prev":["doctors_orders"],"next":["a_reveal_in_ruins"],"depth":9},{"id":"mixed_signals","name":{"en":"Mixed Signals","zh":"混合信号"},"desc":{"en":"Have you spotted any Surveyors; the big round ones? \n\nThey seem to be transmitting data back into orbit, and I can’t help but think it's tied to that signal we picked up. Will you break one open, so we can try to decipher the data?","zh":"你看到过“勘测师”吗，就是像大圆球一样的？它们似乎在向轨道传输数据，我在想这可能跟我们捕捉到的信号有关。你看能不能破拆“勘测师”，这样我们就能尝试解密数据了。"},"trader":"Shani","maps":["buried_city","the_spaceport","the_blue_gate","dam_battlegrounds","riven_tides"],"objectives":[{"en":"Destroy an ARC Surveyor","zh":"摧毁一架ARC“勘测师”"},{"en":"Obtain 1 Surveyor Vault","zh":"获得1个“勘测师”保险库"}],"required":[["surveyor_vault",1]],"rewards":[["photoelectric_cloak",1],["raider_hatch_key",1]],"granted":[["jolt_mine",3],["showstopper",2]],"prev":["dormant_barons"],"depth":9},{"id":"movie_night","name":{"en":"Movie Night","zh":"电影之夜"},"desc":{"en":"Everyone's been on edge ever since rumors of that ARC signal spread. I was thinking a movie night would be a great distraction, but I'm missing some crucial supplies. You'll help me out, yeah?","zh":"自从那个ARC信号的传言传开，大伙儿都一直坐立不安。我一直想搞个电影之夜活动，让大家放松一下神经。但我的投影机缺了一些关键物资。你能帮我找一下吗？"},"trader":"Apollo","objectives":[{"en":"Deliver a Portable TV to Apollo","zh":"将一台便携电视交给阿波罗"},{"en":"On Stella Montis, search the Cultural Archives for old movie tapes","zh":"在星辰山文化档案馆中寻找旧电影录像带"},{"en":"Deliver the Stack of Movie Tapes to Apollo","zh":"将一堆电影录像带交给阿波罗"}],"oneRound":true,"required":[["portable_tv",1],["stack_of_movie_tapes",1]],"rewards":[["showstopper",3],["smoke_grenade",3],["fireworks_box",1]],"granted":[["blue_light_stick",3],["yellow_light_stick",3]],"prev":["with_a_view"],"depth":9},{"id":"settled_in_full","name":{"en":"Settled in Full","zh":"债务结清"},"desc":{"en":"Lucky for you, Dodger's debt can still be settled. Bring me a Bastion Cell. A real one, pulled from a real Bastion. Consider what Dodger owed me transferred to credit for you. Okay?","zh":"算你走运，道奇的债还能结清。给我弄一个“堡垒”电池，必须是从真正的“堡垒”上拆下来的。道奇欠我的债，就抵作你的报酬，怎么样？"},"trader":"Tian Wen","objectives":[{"en":"Destroy a Bastion","zh":"摧毁一个“堡垒”"},{"en":"Deliver a Bastion Cell to Tian Wen","zh":"将“堡垒”电池交给天玟"}],"required":[["bastion_cell",1]],"rewards":[["raider_tokens",30]],"prev":["outstanding_balance"],"depth":9},{"id":"stable_housing","name":{"en":"Stable Housing","zh":"稳固住宅"},"desc":{"en":"You like a certain amount of uncertainty, right? A client wants the contents of a locked safe in Stella Montis. It's intact, so whatever's inside has been there since before the Exodus. Interested?","zh":"你喜欢一定程度的未知因素，对吧？有客户想要星辰山中一个上锁保险柜里的东西。那个柜子完好无损，所以里面的东西在“离巢时代”之前就一直存放在那儿了。有兴趣吗？"},"trader":"Tian Wen","maps":["stella_montis"],"objectives":[{"en":"Go to the Security Bridge","zh":"前往安保区过道桥"},{"en":"Search for the safe in the side room by the third-floor staircases","zh":"在三楼楼梯旁的侧室中搜寻保险柜"},{"en":"Head upstairs to the fourth-floor control room","zh":"上楼前往四楼控制室"},{"en":"Use the Access Card Printer to print a key to the safe","zh":"使用门禁卡打印机打印保险柜钥匙"},{"en":"Search for alternate ways into the safe","zh":"寻找进入保险柜的其他路径"},{"en":"Retrieve the contents of the safe","zh":"取回保险柜内的物品"},{"en":"Deliver the Project Heartwood Blueprints to Tian Wen","zh":"将“常青计划”蓝图交给天玟"}],"oneRound":true,"required":[["project_heartwood_blueprints",1]],"rewards":[["seeker_grenade",5],["lure_grenade",5],["snap_hook",1]],"prev":["with_a_view"],"depth":9},{"id":"test_case","name":{"en":"Test Case","zh":"测试案例"},"desc":{"en":"Hey, question for you. What do you get if you cross a Hornet and Fireball? If your answer is ‘a Firefly’, then we’re on the same page.","zh":"问你个问题，“马蜂”和“火球”结合会是什么？如果你的答案是“萤火虫”，那我们想到一块儿去了。"},"trader":"Apollo","objectives":[{"en":"Deliver a Hornet Driver to Apollo","zh":"将“马蜂”引擎交给阿波罗"},{"en":"Deliver a Fireball Burner to Apollo","zh":"把“火球”燃烧炉交给阿波罗"},{"en":"Destroy a Firefly","zh":"摧毁一个“萤火虫”"},{"en":"Deliver a Firefly Burner to Apollo","zh":"把“萤火虫”燃烧炉交给阿波罗"}],"required":[["hornet_driver",1],["fireball_burner",1],["firefly_burner",1]],"rewards":[["fireworks_box_blueprint",1],["seeker_grenade",3],["blaze_grenade",3]],"prev":["the_league"],"depth":9},{"id":"waking_the_grid","name":{"en":"Waking the Grid","zh":"唤醒安保网络"},"desc":{"en":"There's a problem with our sensor coverage at the Spaceport. The security grid is old, so maybe it's just acting up. If you could get it running again, it'd save me a lot of sleepless nights.","zh":"太空港的传感器覆盖出了问题。考虑到安保网络过于老旧，可能只是故障。如果能让它恢复运行，我就能睡个安稳觉了。"},"trader":"Shani","maps":["the_spaceport"],"objectives":[{"en":"Activate the security sensors in one of the Guard Towers","zh":"在任意守卫塔启动安保传感器"},{"en":"Start the Security Control Center in the Departure Building","zh":"在候机楼中启动安保控制中心"},{"en":"Search for any traces of a security breach in the Arrival Building Data Office","zh":"搜寻到达楼数据办公室的安保入侵痕迹"}],"rewards":[["tactical_mk3_revival",1],["vita_shot",3],["surge_shield_recharger",5]],"prev":["dust_on_the_wires"],"depth":9},{"id":"what_we_left_behind","name":{"en":"What We Left Behind","zh":"遗留之物"},"desc":{"en":"Celeste told me you’re the one who helped her hound me about pitching in more. I’ll say this once: I don’t appreciate the meddling, and I have my own reasons for refusing. I do, however, appreciate the scrap. Since you’re apparently good at tracking it down, I may have a task for you.","zh":"塞莱斯特告诉我了，就是你帮她缠着我，让我做牛做马的。我只说一次：我不喜欢这种干涉，我拒绝也有我自己的理由。不过，我确实感激你提供了那些废料。既然你这么擅长寻找废料，那就分配你个任务吧。"},"trader":"Tian Wen","maps":["buried_city","the_spaceport","dam_battlegrounds"],"objectives":[{"en":"On Buried City, search 2 containers in the Raider Camp beneath the Parking Garage","zh":"前往掩埋废城，在停车场下方的奇袭者营地搜索2个容器"},{"en":"On Dam Battlegrounds, search for anything significant in the South Swamp Outpost","zh":"前往大坝战场，在沼泽南部岗哨寻找重要物品"},{"en":"On Spaceport, search for anything significant in Bilguun's Hideout, next to the Container Storage","zh":"前往太空港，在集装箱仓库旁的比尔根的藏身处寻找重要物品"}],"rewards":[["muzzle_brake_ii",1],["vertical_grip_ii",1],["stable_stock_ii",1]],"prev":["dormant_barons"],"next":["broken_monument"],"depth":9},{"id":"a_reveal_in_ruins","name":{"en":"A Reveal in Ruins","zh":"废墟中的揭示"},"desc":{"en":"I got my hands on a fancy new ESR analyzer; had a whole big reveal planned. One minute it’s here, next minute—poof. Please help?","zh":"我搞到了一台崭新的ESR分析仪。本来计划来个大揭秘的，但是突然之间就不见了。能帮帮忙吗？"},"trader":"Lance","maps":["buried_city"],"objectives":[{"en":"Search for an ESR Analyzer inside any pharmacy in Buried City","zh":"到掩埋废城的任意药店中搜索ESR分析仪"},{"en":"Deliver the ESR Analyzer to Lance","zh":"把ESR分析仪交给兰斯"}],"oneRound":true,"required":[["esr_analyzer",1]],"rewards":[["tactical_mk3_healing",1],["surge_shield_recharger",1]],"prev":["medical_merchandise"],"next":["a_lay_of_the_land"],"depth":10},{"id":"broken_monument","name":{"en":"Broken Monument","zh":"破败的纪念"},"desc":{"en":"I have another special site I need you to search for me. An old battlegrounds, from the First Wave. Raiders nowadays usually pick places like that clean, despite the significance they once held. People forget quickly. Quicker than they should.","zh":"我还有个特殊地点要你帮我找，是“第一波”时期的老战场。虽然这种地方具有重要意义，但如今的奇袭者通常会将之扫荡一空。人们遗忘得太快，快得有些不应该。"},"trader":"Tian Wen","maps":["dam_battlegrounds"],"objectives":[{"en":"Reach the hallowed grounds by the Scrap Yard","zh":"抵达废料场旁边的圣地"},{"en":"Search for a compass near the broken-down vehicles","zh":"在报废车辆附近寻找指南针"},{"en":"Search for the video tape near the cylindrical containers","zh":"在圆柱形容器附近寻找录像带"},{"en":"Search for the old field rations in the Raider camp","zh":"在奇袭者营地搜寻旧的野战口粮"},{"en":"Deliver the First Wave Tape to Tian Wen","zh":"把“第一波”录像带交给天玟"},{"en":"Deliver First Wave Compass to Tian Wen","zh":"把“第一波”指南针交给天玟"},{"en":"Deliver First Wave Rations to Tian Wen","zh":"把“第一波”口粮交给天玟"}],"oneRound":true,"required":[["first_wave_tape",1],["first_wave_compass",1],["first_wave_rations",1]],"rewards":[["arpeggio_i",1],["compensator_ii",1],["medium_ammo",80]],"prev":["what_we_left_behind"],"next":["marked_for_death","straight_record"],"depth":10},{"id":"a_lay_of_the_land","name":{"en":"A Lay of the Land","zh":"地形勘查"},"desc":{"en":"Those distant rumbles are getting less distant with each passing day.\n\nI have a lead on some LiDAR scanners that may help us monitor the tremors. You do want to keep a roof over your head, don’t you?","zh":"轰隆声越来越近了。搞到激光雷达扫描仪就能监测地震，我知道它们在哪。你总不想睡着睡着天塌了吧？"},"trader":"Shani","maps":["the_spaceport"],"objectives":[{"en":"Reach the Jiangsu Warehouse","zh":"抵达江苏仓库"},{"en":"Find the shipping notes in the foreman’s office","zh":"在施工负责人办公室找到货运单据"},{"en":"Locate the scanners in the Flight Control office of Control Tower A6","zh":"在控制塔A6的飞控中心办公室找到扫描仪"},{"en":"Deliver 1 LiDAR Scanners to Shani","zh":"把1台激光雷达扫描仪交给萨尼"}],"oneRound":true,"required":[["lidar_scanner",1]],"rewards":[["dam_testing_annex_key",1],["zipline",3],["smoke_grenade",2]],"prev":["a_reveal_in_ruins"],"next":["eyes_in_the_sky"],"depth":11},{"id":"marked_for_death","name":{"en":"Marked for Death","zh":"死亡标记"},"desc":{"en":"Someone has been lifting supplies from my drop-off point in Buried City. I’ve set up a trap, but I need someone to check it for me.","zh":"有人一直从我在掩埋废城的投放点偷取物资。我设了一个陷阱，但需要有人去帮我检查一下触发情况。"},"trader":"Tian Wen","maps":["buried_city"],"objectives":[{"en":"Reach the Su Durante Warehouses in the Outskirts in Buried City","zh":"抵达掩埋废城郊区的苏杜兰仓库"},{"en":"Search for Tian Wen's cache near the Warehouses","zh":"在仓库附近搜索天玟的储物箱"},{"en":"Follow the clues","zh":"追踪线索"}],"rewards":[["shotgun_choke_ii",1],["angled_grip_ii",1]],"prev":["broken_monument"],"next":["market_correction"],"depth":11},{"id":"straight_record","name":{"en":"Straight Record","zh":"理顺记录"},"desc":{"en":"Back during the First Wave, my squad and I built a trap out by the Dam. Overloaded a generator, turned it into a makeshift ARC trap. Now I hear Raiders are using it to cut comms and spring ambushes on each other. I need you to end it.","zh":"“第一波”期间，我们小队在大坝边上设了一个陷阱，就是把发电机超载，当成临时的ARC诱捕器。现在听说奇袭者之间用它来切断通讯打伏击。你帮我去毁了它。"},"trader":"Celeste","maps":["dam_battlegrounds"],"objectives":[{"en":"Reach Victory Ridge","zh":"抵达凯旋岭"},{"en":"Find the old EMP trap","zh":"找到旧的电磁脉冲陷阱"},{"en":"Disable the first power switch","zh":"关闭第一个电源开关"},{"en":"Disable the second power switch","zh":"关闭第二个电源开关"},{"en":"Disable the third power switch","zh":"关闭第三个电源开关"},{"en":"Shut down the EMP trap","zh":"关闭电磁脉冲陷阱"}],"rewards":[["medium_gun_parts",5],["advanced_mechanical_components",3]],"granted":[["binoculars",1],["defibrillator",1]],"prev":["broken_monument"],"next":["keeping_the_memory"],"depth":11},{"id":"eyes_in_the_sky","name":{"en":"Eyes in the Sky","zh":"天空之眼"},"desc":{"en":"Those LiDAR scanners you found work best when put in high locations. I’ve identified a few good spots around the Rust Belt; hope you’re surefooted.","zh":"你找到的激光雷达扫描仪放在高处效果最好。我在锈带标了几个好位置，但愿你不会恐高。"},"trader":"Shani","maps":["buried_city","the_spaceport","dam_battlegrounds"],"objectives":[{"en":"On Dam Battlegrounds, install a LiDAR Scanner at the top of the Control Tower","zh":"前往大坝战场，将激光雷达扫描仪安装到控制塔顶部"},{"en":"On Spaceport, install a LiDAR Scanner at the Communications Tower","zh":"前往太空港，将激光雷达扫描仪安装到通讯塔上"},{"en":"On Buried City, install a LiDAR Scanner on top of the Galleria sign","zh":"前往掩埋废城，将激光雷达扫描仪安装到画廊招牌顶部"}],"rewards":[["tagging_grenade",3],["vita_spray",1],["yellow_light_stick",5]],"granted":[["zipline",1]],"prev":["a_lay_of_the_land"],"next":["after_rain_comes","a_balanced_harvest","back_on_top"],"depth":12},{"id":"keeping_the_memory","name":{"en":"Keeping the Memory","zh":"铭记于心"},"desc":{"en":"I lost my cool a bit when I sent you after that trap. I don’t usually lose my temper, but the First Wave… We went through a lot, back then. Lost a lot of people. It’s still a bit of a raw wound for me, but I want you to understand.","zh":"当初派你去处理那个陷阱时，我有点失控了。我一般不轻易发火，但“第一波”……我们那时经历了很多苦难，失去了很多人。我至今还没有走出来，但我想让你理解它的意义。"},"trader":"Celeste","maps":["dam_battlegrounds"],"objectives":[{"en":"Reach the wreckage in the Formicai Hills","zh":"抵达蚁丘山的残骸处"},{"en":"Search for the missing helmet","zh":"寻找丢失的头盔"},{"en":"Return the helmet to the memorial","zh":"把头盔带回纪念碑"}],"oneRound":true,"rewards":[["simple_gun_parts",5],["duct_tape",5],["magnet",5]],"prev":["straight_record"],"next":["echoes_of_victory_ridge"],"depth":12},{"id":"market_correction","name":{"en":"Market Correction","zh":"矫正市场规则"},"desc":{"en":"That theft before? Doesn’t look like a coincidence anymore. Some of the competition from Toledo is setting up shop where they don’t belong. I want their cache sabotaged, preferably before they get too comfortable.","zh":"之前那次失窃事件，现在看来不像是巧合。我们来自托雷多的竞争对手正在不属于他们的地方建立据点。我想破坏他们的储物箱——最好在他们站稳脚跟之前。"},"trader":"Tian Wen","maps":["buried_city"],"objectives":[{"en":"Locate the cache near Marano Station","zh":"找到马拉诺车站附近的储物箱"},{"en":"Sabotage the cache","zh":"破坏储物箱"}],"oneRound":true,"rewards":[["silencer_ii",1],["extended_light_mag_i",1],["compensator_i",1]],"prev":["marked_for_death"],"next":["eyes_on_the_prize"],"depth":12},{"id":"a_balanced_harvest","name":{"en":"A Balanced Harvest","zh":"丰富收获"},"desc":{"en":"Our food production is finally enough to meet our basic needs, but what we really need now is variety. I have a lead on some agricultural research from before the First Wave. Are you in?","zh":"我们的食物生产终于足以满足我们的基本需求了，但现在真正需要的是多样化。我有一些关于“第一波”之前的农业研究的线索。有兴趣吗？"},"trader":"Celeste","maps":["dam_battlegrounds"],"objectives":[{"en":"Go to the Research & Administration building","zh":"前往研究与行政区大楼"},{"en":"Locate Lab 1 on the upper floor above the reception","zh":"找到接待前台上方楼层的1号实验室"},{"en":"Search for any traces of the agricultural research project","zh":"寻找农业研究项目的蛛丝马迹"}],"oneRound":true,"rewards":[["advanced_mechanical_components",3],["medium_gun_parts",3],["steel_spring",10]],"prev":["eyes_in_the_sky"],"next":["untended_garden"],"depth":13},{"id":"after_rain_comes","name":{"en":"After Rain Comes","zh":"风雨过后"},"desc":{"en":"I know, I know! The power's down in sector—\nOh, hey. A flash flood took out some of our solar panels in Buried City, and the generators only hold on for so long.\n\nDo us all a solid when you're up there, OK?","zh":"我知道，我知道！有个地区的电源被切断了……\n哦，嗨。一场突发洪水摧毁了我们在掩埋废城的一些太阳能面板，偏偏发电机又快要撑不住了。\n\n如果你到了那边，能不能帮我们修理一下？"},"trader":"Celeste","maps":["buried_city"],"objectives":[{"en":"Find the flooded solar panels nearby the Grandioso Apartments","zh":"到奢华公寓附近找到被淹的太阳能面板"},{"en":"Repair the solar panels using 5 Wires and 2 Batteries","zh":"使用5根导线和2块电池修理太阳能面板"}],"rewards":[["blue_light_stick",5],["antiseptic",3],["durable_cloth",5]],"granted":[["zipline",1]],"prev":["eyes_in_the_sky"],"next":["water_troubles"],"depth":13},{"id":"echoes_of_victory_ridge","name":{"en":"Echoes of Victory Ridge","zh":"凯旋岭的回声"},"desc":{"en":"Did you feel any tremors last night? Me neither. But apparently the ground shifted at some point, and in the process it unearthed an old First Wave outpost that’d been blocked by debris. I’d like you to get in there quick, before anyone else does.","zh":"你昨晚感觉到有震动吗？我也没有。但显然地面在某个时间点被移动了，在这个过程中，一个被废墟阻塞的旧“第一波”哨站暴露了出来。我想让你尽快进去探查一下，以防被别人捷足先登。"},"trader":"Celeste","maps":["dam_battlegrounds"],"objectives":[{"en":"Reach Victory Ridge","zh":"抵达凯旋岭"},{"en":"Retrieve the battle plans from the hideout under the broken highway","zh":"从断裂高速公路下的藏身处取回作战计划"},{"en":"Deliver Major Aiva's Patch to Celeste","zh":"将艾娃少校的臂章交给塞莱斯特"}],"oneRound":true,"required":[["major_aivas_patch",1]],"rewards":[["crude_explosives",6],["processor",2],["music_box",1]],"prev":["keeping_the_memory"],"next":["unexpected_initiative"],"depth":13},{"id":"eyes_on_the_prize","name":{"en":"Eyes on the Prize","zh":"目光长远"},"desc":{"en":"Everything’s been calm around my drop-offs since you helped out, but that doesn’t mean it’ll stay that way for long. I’ve set up surveillance at one of my most used spots in Buried City, to prevent future tampering. Only problem is, it needs power to go live.","zh":"自从你出手相助之后，我的投放点周围一直很平静，但这种情况估计不会持续太久。我在掩埋废城最常用的一个点设置了监控，以防止未来有人打它的歪主意。唯一的问题是，它需要电力才能启动。"},"trader":"Tian Wen","maps":["buried_city"],"objectives":[{"en":"Find the secluded roof terrace south-west of the Southern Station, look for blue tarps.","zh":"寻找位于南侧地铁站西南边的隐蔽屋顶露台，并在那找到蓝色防水布。"},{"en":"Rewire the solar panel using 3 Wires","zh":"使用3根导线给太阳能面板重新接线"}],"rewards":[["extended_shotgun_mag_ii",1],["extended_medium_mag_ii",1]],"prev":["market_correction"],"next":["industrial_espionage"],"depth":13},{"id":"industrial_espionage","name":{"en":"Industrial Espionage","zh":"工业间谍"},"desc":{"en":"With my own stashes secured, I think it might be time to keep a closer eye on the competition so this doesn’t happen again.","zh":"既然我自己的藏货安全了，也许是时候更密切地监视竞争对手，以免这种事再次发生。"},"trader":"Tian Wen","maps":["buried_city"],"objectives":[{"en":"Find Tian Wen's weapon cache near the Gas Station in the Outskirts","zh":"在郊区的加油站附近找到天玟的武器储物箱"},{"en":"Deliver the Burletta to the rival weapon cache","zh":"将布尔莱塔送至对手的武器储物箱"},{"en":"Plant a bug on the weapon cache","zh":"在武器箱上安装窃听器"}],"rewards":[["burletta_blueprint",1],["mechanical_components",3],["simple_gun_parts",3]],"granted":[["burletta_i",1]],"prev":["eyes_on_the_prize"],"next":["unexpected_initiative"],"depth":14},{"id":"untended_garden","name":{"en":"Untended Garden","zh":"无人照看的农园"},"desc":{"en":"According to the files you found in the lab, the cultivation researchers were actually the ones who set up the hydroponic domes out in the swamp. Sounds like the most obvious place to search next, don’t you think?","zh":"根据你在实验室中找到的文件，在沼泽中建立水栽培穹顶的正是那些种植研究员。下一个调查地点明盘了，你说是吧？"},"trader":"Celeste","maps":["dam_battlegrounds"],"objectives":[{"en":"Go to the Hydroponic Dome Complex","zh":"前往水培穹顶综合体"},{"en":"Access the data archive in one of the domes","zh":"访问一个穹顶的数据库"},{"en":"Upload the data to the computer terminal in any Field Depot","zh":"把数据上传到任意前线仓库中的电脑终端"}],"oneRound":true,"rewards":[["advanced_mechanical_components",3],["heavy_gun_parts",3],["canister",5]],"prev":["a_balanced_harvest"],"next":["the_root_of_the_matter"],"depth":14},{"id":"the_root_of_the_matter","name":{"en":"The Root of the Matter","zh":"源头之种"},"desc":{"en":"We're in luck. The notes you found last time were written by the lead researcher. When the project went under, it seems she took some of the seed samples and sealed them away in a secure location.","zh":"你的手气不错，上次找到的笔记是由首席研究员撰写的。当项目失败时，她似乎带走了一些种子样本并把它们密封在了一个安全的地方。"},"trader":"Celeste","maps":["buried_city"],"objectives":[{"en":"Go to the Research Building","zh":"前往研究大楼"},{"en":"Search for the seed vault in the \"room with a great view\"","zh":"在“视野绝佳的房间”里寻找种子库"},{"en":"Deliver the Experimental Seed Sample to Celeste","zh":"将实验型种子样本交给塞莱斯特"}],"oneRound":true,"required":[["experimental_seed_sample",1]],"rewards":[["coins",1000]],"prev":["untended_garden"],"next":["water_troubles"],"depth":15},{"id":"unexpected_initiative","name":{"en":"Unexpected Initiative","zh":"计划不如变化快"},"desc":{"en":"I’m setting up a greenhouse, to help boost our food production. I’m doing Celeste a solid, alright? That’s all. But enough about that. I’ve got all the details worked out, but I’ll need supplies, and I’m not hauling them alone.","zh":"我正在搭建一个温室，以帮助提高食物产量。我这是在帮塞莱斯特一个忙，仅此而已。不过不说这个了。我已经规划好了所有细节，但需要物资，而且单凭我一个人可搞不来。"},"trader":"Tian Wen","maps":["buried_city"],"objectives":[{"en":"Reach the Grandioso Apartments in Buried City","zh":"抵达掩埋废城的奢华公寓"},{"en":"Search for a Moisture Meter on the rooftop of the Grandioso Apartments","zh":"在奢华公寓屋顶搜索水分测量仪"},{"en":"Reach Piazza Roma in Buried City","zh":"抵达掩埋废城的罗马广场"},{"en":"Search for a Nutrient Meter in the broken rooftop gardens at Piazza Roma","zh":"在罗马广场破败的屋顶花园寻找营养测量仪"},{"en":"Deliver a Nutrient Meter to Tian Wen","zh":"将营养测量仪交给天玟"},{"en":"Deliver a Moisture Meter to Tian Wen","zh":"将水分测量仪交给天玟"}],"oneRound":true,"required":[["nutrient_meter",1],["moisture_meter",1]],"rewards":[["il_toro_i",1],["shotgun_ammo",40],["shotgun_choke_ii",1]],"prev":["industrial_espionage","echoes_of_victory_ridge"],"next":["a_symbol_of_unification"],"depth":15},{"id":"a_symbol_of_unification","name":{"en":"A Symbol of Unification","zh":"团结的象征"},"desc":{"en":"Y’know, back in the day we actually used to have a flag - well, a scrap of cloth more than anything. Still, seeing it meant you knew you had allies nearby, that you were on your own home turf. So, I was thinking…","zh":"话说，早年我们真有一面旗子——好吧，算是块破布。但看见它就代表附近有战友，算到了自家地盘。所以我在想……"},"trader":"Celeste","maps":["dam_battlegrounds"],"objectives":[{"en":"Reach the Formicai Outpost in Dam Battlegrounds","zh":"抵达大坝战场的蚁丘山哨站"},{"en":"Locate the flag at the Formicai Outpost","zh":"在蚁丘山哨站找到旗帜"},{"en":"Hoist the flag on the small platform overlooking the Red Lake","zh":"在俯瞰红湖的小平台上扬起旗帜"}],"oneRound":true,"rewards":[["mod_components",3],["duct_tape",5]],"prev":["unexpected_initiative"],"next":["the_majors_footlocker","celestes_journals","out_of_the_shadows"],"depth":16},{"id":"water_troubles","name":{"en":"Water Troubles","zh":"水源问题"},"desc":{"en":"If you’re here to complain about the water, join the club. I’ve been fielding complaints all day. Something is definitely up with it, and I need some help to sort it out.","zh":"如果你是来投诉水质问题的，排队去吧。我这一整天都在处理投诉。肯定是什么地方出了问题，我想找人去排查一下。"},"trader":"Celeste","maps":["dam_battlegrounds"],"objectives":[{"en":"Locate the Flood Access Tunnel under the Red Lake Balcony","zh":"找到红湖阳台下方的泄洪隧道"},{"en":"Find the intake to the District's Water Supply","zh":"找到区域供水的入口"},{"en":"Sample the water","zh":"给水源取样"}],"oneRound":true,"rewards":[["mechanical_components",3],["simple_gun_parts",3],["steel_spring",3]],"prev":["after_rain_comes","the_root_of_the_matter"],"next":["into_the_fray","source_of_the_contamination"],"depth":16},{"id":"celestes_journals","name":{"en":"Celeste’s Journals","zh":"塞莱斯特的日记"},"desc":{"en":"Okay, so this is awkward… I lost two of my journals during some outpost inspections last time I went topside. Could you head out there and try to find them back before someone else stumbles on them?","zh":"说起来有点尴尬……上次我去上层进行哨站检查时丢了两本日记。你能去帮忙找回来吗？我不想日记落到别人手里。"},"trader":"Celeste","maps":["dam_battlegrounds"],"objectives":[{"en":"Retrieve Celeste’s Journals from the South Swamp Outpost","zh":"从沼泽南部岗哨取回塞莱斯特的日记"},{"en":"Retrieve Celeste’s Journals from Raider Outpost East","zh":"从奇袭者岗哨东侧取回塞莱斯特的日记"},{"en":"Deliver 2 Journals to Celeste","zh":"将2本日记交给塞莱斯特"}],"oneRound":true,"required":[["celeste_journal",2]],"rewards":[["magnetic_accelerator",1],["heavy_gun_parts",3],["exodus_modules",1]],"prev":["a_symbol_of_unification"],"next":["back_on_top"],"depth":17},{"id":"out_of_the_shadows","name":{"en":"Out of the Shadows","zh":"走出阴影"},"desc":{"en":"Did you see the flags? The time for cowering is over. You’ve been more than battle-tested, from what I hear; think you can take on a Rocketeer?","zh":"你看到那些旗帜了吗？躲躲闪闪的日子已经结束。我听说你身经百战了，你觉得自己能对付“火箭手”吗？"},"trader":"Shani","maps":["buried_city","the_spaceport","the_blue_gate","dam_battlegrounds","riven_tides"],"objectives":[{"en":"Destroy a Rocketeer","zh":"摧毁一个“火箭手”"},{"en":"Obtain a Rocketeer Driver","zh":"获得一个“火箭手”引擎"}],"required":[["rocketeer_driver",1]],"rewards":[["surge_shield_recharger",3],["wolfpack",1],["wolfpack",1]],"granted":[["medium_shield",1],["combat_mk2",1]],"prev":["a_symbol_of_unification","sparks_fly"],"next":["combat_recon"],"depth":17},{"id":"source_of_the_contamination","name":{"en":"Source of the Contamination","zh":"污染源头"},"desc":{"en":"I’m not saying our water’s been tampered with, but based on your samples, I can’t rule out the possibility either. Would you return to the Dam and see what’s wrong?","zh":"我不是说我们的水源被动了手脚，但根据你带回来的样本，也不能排除这种可能性。能否返回大坝，查清楚哪里出了问题？"},"trader":"Celeste","maps":["dam_battlegrounds"],"objectives":[{"en":"Reach the Water Treatment Building in The Dam","zh":"抵达大坝的水处理厂大楼"},{"en":"Search for the Flood Spill Intake near the Swamp","zh":"在沼泽附近搜索溢洪道进水口"},{"en":"Investigate any suspicious objects","zh":"调查任何可疑物品"}],"rewards":[["steel_spring",5],["duct_tape",5],["mod_components",1]],"prev":["water_troubles"],"next":["switching_the_supply"],"depth":17},{"id":"the_majors_footlocker","name":{"en":"The Major’s Footlocker","zh":"少校的储物柜"},"desc":{"en":"I have another job. It’s.. about my mom.\n\nThose First Wave sites I sent you to before? I actually hoped you’d find something of my mother’s. She fought in the Raider resistance. It was a long shot; but now I've got an actual lead.","zh":"我还有个任务，是关于……我母亲的。\n\n之前我派你去那些“第一波”遗址，其实是希望你能找到我母亲的某样东西，她曾作为奇袭者反抗军战斗过。我知道希望很渺茫，但这次我找到了可靠的线索。"},"trader":"Tian Wen","maps":["dam_battlegrounds"],"objectives":[{"en":"Search for Major Aiva's mementos in the apartments northwest of The Dam","zh":"在大坝西北方向的公寓中搜寻艾娃少校的纪念品"},{"en":"Deliver Major Aiva's Mementos to Tian Wen","zh":"将艾娃少校的纪念品交给天玟"}],"oneRound":true,"required":[["major_aivas_mementos",1]],"rewards":[["hullcracker_blueprint",1]],"prev":["a_symbol_of_unification"],"next":["back_on_top"],"depth":17},{"id":"back_on_top","name":{"en":"Back on Top","zh":"重占上风"},"desc":{"en":"Guess what? Shani asked me to help out with something, and for once, I’m actually glad she did. We’re setting up new outposts topside! Or, planning to, at least. Can you believe it?","zh":"猜怎么着？萨尼请我帮忙办点事，这次我居然挺高兴的。我们要在上层建立新的哨站了！或者说，至少是计划要建。你敢信吗？"},"trader":"Tian Wen","maps":["buried_city","the_spaceport","the_blue_gate","dam_battlegrounds"],"objectives":[{"en":"On Dam Battlegrounds, mark the Pattern House","zh":"在大坝战场标记壁画屋"},{"en":"On The Blue Gate, mark the white lookout tower south of the Warehouse Complex","zh":"在蓝门标记仓储综合区以南的白色瞭望塔"},{"en":"On Spaceport, mark the South Trench Tower","zh":"在太空港标记南壕沟塔"},{"en":"On Buried City, mark the building with the mural in the Buried Properties","zh":"在掩埋废城标记埋没的楼群内带壁画的建筑"}],"rewards":[["renegade_i",1],["stable_stock_iii",1],["medium_ammo",80]],"other":[{"en":"18x Raids","zh":"18 局"}],"prev":["the_majors_footlocker","eyes_in_the_sky","celestes_journals"],"next":["our_presence_up_there"],"depth":18},{"id":"switching_the_supply","name":{"en":"Switching the Supply","zh":"更换水源"},"desc":{"en":"There is a reservoir beneath the Spaceport; if we manage to route that water here, that should buy us time to deal with the contamination.","zh":"太空港下面有一个水库。如果能把那里的水引到这里来，就能为我们争取一些时间来解决污染问题。"},"trader":"Celeste","maps":["the_spaceport"],"objectives":[{"en":"Find the tunnels under the Spaceport","zh":"找到太空港下面的隧道"},{"en":"Find and turn the valve in the tunnels under Spaceport","zh":"到太空港下面的隧道中找到并转动阀门"}],"oneRound":true,"rewards":[["spaceport_trench_tower_key",1],["synthesized_fuel",3]],"prev":["source_of_the_contamination"],"next":["a_warm_place_to_rest"],"depth":18},{"id":"a_warm_place_to_rest","name":{"en":"A Warm Place To Rest","zh":"温暖的休憩之地"},"desc":{"en":"A customer of mine saw a family taking cover in an old encampment in Buried City. I'll pay anyone who manages to find them and escort them back to safety.","zh":"我的一个客户看到有一家人在掩埋废城中的一个旧营地中避难。谁要是能找到并护送他们回到安全地带，可以到我这来领赏。"},"trader":"Apollo","maps":["buried_city"],"objectives":[{"en":"Locate the Abandoned Highway Camp","zh":"找到废弃的高速公路营地"},{"en":"Search for any signs of survivors","zh":"寻找幸存者的痕迹"},{"en":"Follow the red markers","zh":"追踪红色标记"},{"en":"Inspect the grave","zh":"检查坟墓"}],"rewards":[["noisemaker",3],["blue_light_stick",5],["rosary",1]],"prev":["switching_the_supply"],"next":["prescriptions_of_the_past"],"depth":19},{"id":"our_presence_up_there","name":{"en":"Our Presence up There","zh":"我们在上面的据点"},"desc":{"en":"ARC may be changing, but we’re finally changing with it. Let’s finish up those outposts and revolutionize the way we track them, flank them, and smash them to bits.","zh":"ARC一直在改变，现在我们终于也可以与时俱进了。我们来把那些哨站建完，之后就能彻底改变追踪、包抄以及有效摧毁它们的方式。"},"trader":"Shani","maps":["dam_battlegrounds"],"objectives":[{"en":"Visit the Pattern House in The Dam","zh":"前往大坝中的壁画屋"},{"en":"Find and flip the power switch","zh":"找到并扳动电源开关"},{"en":"Complete the antenna installation on the roof","zh":"完成屋顶上的天线安装"}],"oneRound":true,"rewards":[["buried_city_town_hall_key",1],["raider_hatch_key",1],["jolt_mine",3]],"prev":["back_on_top"],"next":["lost_in_transmission"],"depth":19},{"id":"lost_in_transmission","name":{"en":"Lost in Transmission","zh":"迷失在传输中"},"desc":{"en":"I have equipment set up at the Spaceport, to monitor ARC’s movements. My connection broke down just now — I need you to head to the Control Towers and help me retrieve my logs.","zh":"我在太空港安装了一套设备，用于监测ARC的动向。刚才连接中断了——你去趟控制塔，帮我取回日志。"},"trader":"Shani","maps":["the_spaceport"],"objectives":[{"en":"Visit Control Tower A6","zh":"前往控制塔A6"},{"en":"Find a spare key","zh":"找到一把备用钥匙"},{"en":"Reach the top of Control Tower A6","zh":"抵达控制塔A6顶部"},{"en":"Establish a connection from the terminal","zh":"通过终端建立连接"}],"oneRound":true,"rewards":[["snap_hook",1]],"granted":[["spaceport_control_tower_key",1]],"prev":["our_presence_up_there"],"next":["communication_hideout"],"depth":20},{"id":"prescriptions_of_the_past","name":{"en":"Prescriptions of the Past","zh":"昔日的药方"},"desc":{"en":"I’ve been curious about the medical area in the Spaceport for a while now. Something tells me it’s got just what I need to become the undeniable champion of this place.","zh":"我一直对太空港的医疗区域很好奇。直觉告诉我，这里有能让我成为这座城区绝对王者的契机。"},"trader":"Lance","maps":["the_spaceport"],"objectives":[{"en":"Visit the Departure Building in Spaceport","zh":"前往太空港中的候机楼"},{"en":"Find the Medical Exam Room inside the Departure Building","zh":"找到候机楼里的体检室"},{"en":"Search for the records","zh":"寻找医疗记录"}],"oneRound":true,"rewards":[["heavy_shield",1],["tactical_mk3_healing",1],["adrenaline_shot",3]],"prev":["a_warm_place_to_rest"],"next":["power_out"],"depth":20},{"id":"communication_hideout","name":{"en":"Communication Hideout","zh":"通讯隐蔽处"},"desc":{"en":"We've been losing signals in some areas of Buried City—my guess is that our equipment is acting up. You’re quite skilled with repairs, aren’t you? Could you check it out?","zh":"我们在掩埋废城的某些区域一直丢失信号。可能是我们的设备出问题了。你很擅长修理，对吧？能去检查一下吗？"},"trader":"Shani","maps":["buried_city"],"objectives":[{"en":"Reach the Red Tower in Old Town","zh":"抵达老城区的红塔"},{"en":"Find missing battery cell","zh":"找到丢失的电池单元"},{"en":"Install the battery cell in the Generator","zh":"将电池单元安装到发电机中"},{"en":"Enable the power on the Generator","zh":"启动发电机的电源"},{"en":"Boot the antenna terminal near the Red Tower","zh":"启动红塔附近的天线终端"}],"oneRound":true,"rewards":[["anvil_iii",1],["heavy_ammo",40]],"prev":["lost_in_transmission"],"next":["into_the_fray"],"depth":21},{"id":"power_out","name":{"en":"Power Out","zh":"电力不足"},"desc":{"en":"This goes beyond bad luck. Something—or someone—has knocked out some of our electrical substations. The engineer I sent out to fix it hasn’t returned, so I need all available Raiders to look into it. That includes you.","zh":"这不仅仅是倒霉了。某些东西或者某些人，摧毁了我们的部分变电站。我派去修理的工程师没有回来，所以我不得不调派所有能用的奇袭者去调查这件事。包括你。"},"trader":"Celeste","maps":["the_spaceport"],"objectives":[{"en":"Find the Electrical Substation south of the Spaceport","zh":"到太空港南部找到变电站"},{"en":"Find any sign of the missing engineer","zh":"寻找失联工程师的踪迹"},{"en":"Install the fuse","zh":"安装保险丝"},{"en":"Restore the power","zh":"恢复电力"}],"oneRound":true,"rewards":[["wires",5],["explosive_compound",5],["oil",5]],"prev":["prescriptions_of_the_past"],"next":["flickering_threat"],"depth":21},{"id":"flickering_threat","name":{"en":"Flickering Threat","zh":"初露端倪的威胁"},"desc":{"en":"My usual engineer is still healing from his wounds, and has been loopy for days. We can’t afford to be at half-grid until he heals; I need someone to pick up his wrench in the mean time.","zh":"我平时用的工程师还在养伤，已经神志不清好几天了。在他痊愈之前，这里总不能处于半瘫痪状态，需要有人在这段时间接手他的工作。"},"trader":"Celeste","maps":["dam_battlegrounds"],"objectives":[{"en":"Find the Generator Room","zh":"找到发电机房"},{"en":"Repair the Generator using 4 Wires","zh":"使用4根导线修理发电机"},{"en":"Find the Ventilation Shaft","zh":"找到通风井"},{"en":"Enable the power via the power switch underneath the stairs","zh":"用楼梯下方的电源开关启动电源"}],"rewards":[["medium_gun_parts",5],["advanced_mechanical_components",3]],"prev":["power_out"],"next":["bees"],"depth":22},{"id":"into_the_fray","name":{"en":"Into the Fray","zh":"投入战斗"},"desc":{"en":"It used to be their world, up there. Nobody to challenge their claim. \n\nYet here we are. More outposts. More intel. More firepower. If I didn’t know better, I’d say we’ve got quite a bit of fight left in us.","zh":"上面曾经是它们的地盘，无人能撼动其霸权。可如今呢？哨站越建越多，情报网越铺越广，火力装备越来越强。要是不知情，我甚至会说——我们这帮人，骨子里的血性可半点没少。"},"trader":"Shani","maps":["buried_city","the_spaceport","the_blue_gate","dam_battlegrounds","riven_tides"],"objectives":[{"en":"Destroy a Leaper","zh":"摧毁一个“跳跃者”"},{"en":"Obtain a Leaper Pulse Unit","zh":"获得一个“跳跃者”脉冲单元"}],"required":[["leaper_pulse_unit",1]],"rewards":[["vulcano_iii",1],["shotgun_ammo",40]],"prev":["water_troubles","communication_hideout"],"next":["combat_recon","paving_the_way"],"depth":22},{"id":"bees","name":{"en":"Bees!","zh":"蜜蜂！"},"desc":{"en":"Bees! There are bees still around! While I’m no expert, our greenhouse crew desperately wants some.","zh":"蜜蜂！蜜蜂居然没有灭绝！虽然我不是专家，但我们的温室团队非常想要。"},"trader":"Celeste","maps":["the_blue_gate"],"objectives":[{"en":"Reach the Olive Grove in Blue Gate","zh":"抵达蓝门区域的橄榄树林"},{"en":"Search for bee hives around the Olive Grove","zh":"在橄榄树林附近寻找蜂巢"}],"oneRound":true,"rewards":[["advanced_electrical_components",1],["sensors",3]],"granted":[["yellow_light_stick",5]],"prev":["flickering_threat"],"next":["espresso"],"depth":23},{"id":"combat_recon","name":{"en":"Combat Recon","zh":"战斗侦察"},"desc":{"en":"With those Bombardiers roaming around, ARC has found an entirely new way to flush Raiders out of cover. \n\nIf you’re hoping to take one down, you’ll need to sharpen your skills and your strategy.","zh":"“投弹手”开始四处游荡，ARC显然找到了一种全新的方法将奇袭者从掩体中逼出来。\n\n如果想要击落“投弹手”，就需要提升你的技巧和策略。"},"trader":"Shani","maps":["buried_city"],"objectives":[{"en":"Scope out a cover spot in the Parking Garage staircases","zh":"探查停车场楼梯间的一个掩护点"},{"en":"Scope out a cover spot in the buses near Marano Park","zh":"探查马拉诺公园附近巴士中的掩护点"},{"en":"Scope out a cover spot in the attics around Main Street","zh":"探查主街周围阁楼的一个掩护点"},{"en":"Destroy 2 Spotters","zh":"摧毁2个“侦察员”"},{"en":"Deliver a Spotter Relay to Shani","zh":"将一个“侦察员”中继器交给萨尼"}],"required":[["spotter_relay",1]],"rewards":[["firecracker",5],["fireworks_box",1]],"granted":[["binoculars",1]],"prev":["into_the_fray","out_of_the_shadows"],"next":["bombing_run"],"depth":23},{"id":"paving_the_way","name":{"en":"Paving the Way","zh":"开辟道路"},"desc":{"en":"For an entire sector to collapse like that… No wonder people are scared. We need to reinforce beyond anything we’ve done before, and we can’t do it alone.","zh":"整片区域就这样坍塌……难怪大家这么害怕。我们必须进行前所未有的加固工程，但单靠我们不行。"},"trader":"Apollo","maps":["the_blue_gate","buried_city","dam_battlegrounds"],"objectives":[{"en":"Go to any ENELICA building","zh":"前往任意艾纳里卡建筑"},{"en":"Search for a notice board with a note from the researcher","zh":"搜寻写有研究员笔记的公告板"},{"en":"On Buried City, reach the top floor above the Convinio in Piazza Roma","zh":"在掩埋废城，抵达罗马广场中康维尼奥上方的顶层"},{"en":"Find the researcher's flat and search for any research data","zh":"找到研究员的公寓并搜寻研究数据"}],"rewards":[["raider_hatch_key",1],["seeker_grenade",3],["advanced_electrical_components",1]],"prev":["into_the_fray"],"next":["deciphering_the_data"],"depth":23},{"id":"bombing_run","name":{"en":"Bombing Run","zh":"以下犯上"},"desc":{"en":"Now, time to see if that recon paid off. If we can teach Raiders to effectively counter Bombardiers up there, we’d be a lot safer down here.","zh":"现在，是时候看看侦察的成果了。如果我们能教会奇袭者有效对抗天上的“投弹手”，我们在地下的安全就能大大提升。"},"trader":"Shani","objectives":[{"en":"Destroy a Bombardier","zh":"摧毁一个“投弹手”"},{"en":"Deliver a Bombardier Cell to Shani","zh":"将一个“投弹手”电池交给萨尼"}],"required":[["bombardier_cell",1]],"rewards":[["raider_tokens",30]],"prev":["combat_recon"],"depth":24},{"id":"deciphering_the_data","name":{"en":"Deciphering The Data","zh":"解密数据"},"desc":{"en":"If the data you found can keep the ceiling from collapsing, we have no time to spare.\n\nI know of a few magnetic decryptors around Acerra Spaceport, from back during the Exodus. They might still be working.","zh":"如果你找到的数据能防止天花板坍塌，那我们必须立即行动，刻不容缓。\n\n我知道在阿切拉太空港周围有几台“离巢时代”遗留的磁力解密器，可能仍能运作。"},"trader":"Shani","maps":["the_spaceport"],"objectives":[{"en":"Use the Magnetic Decryptor in the Fuel Control Building","zh":"在燃料控制大楼使用磁力解密器"},{"en":"Reach the Arrival Building in Spaceport","zh":"抵达太空港中的到达楼"},{"en":"Use the Magnetic Decryptor on the top floor of the Arrival Building","zh":"在到达楼顶层使用磁力解密器"}],"rewards":[["defibrillator",3],["trailblazer",3]],"prev":["paving_the_way"],"next":["groundbreaking"],"depth":24},{"id":"espresso","name":{"en":"Espresso","zh":"浓缩咖啡"},"desc":{"en":"A Raider came into my shop earlier, to trade some grenades for a machine she found in Buried City. She said it makes coffee, but it seems to be missing a few parts. Up for a job?","zh":"早些时候，一个奇袭者来到我店里，想用她在掩埋废城找到的一台机器换一些手雷。她说那台机器能做咖啡，但好像缺了一些零件。想接这个任务吗？"},"trader":"Apollo","maps":["buried_city"],"objectives":[{"en":"Find an espresso machine to salvage for spare parts","zh":"找到一台浓缩咖啡机，拆取可用零件"},{"en":"Get the Espresso Machine Parts for Apollo","zh":"为阿波罗找到浓缩咖啡机零件"}],"oneRound":true,"required":[["espresso_machine_parts",1]],"rewards":[["coffee_pot",1],["adrenaline_shot",3]],"prev":["bees"],"next":["life_of_a_pharmacist"],"depth":24},{"id":"groundbreaking","name":{"en":"Groundbreaking","zh":"突破性进展"},"desc":{"en":"Data or no data: we’ll learn how to make this place earthquake-proof. With a research this in-depth, there’s bound to be a paper trail somewhere.","zh":"无论有没有数据：我们将学会如何让这个地方抗震。如此深入的研究，必定会留下书面记录。"},"trader":"Apollo","maps":["the_blue_gate"],"objectives":[{"en":"Find a spare Blue Gate Communication Tower Key","zh":"找到备用的蓝门通讯塔钥匙"},{"en":"Enter the locked room at Pilgrim's Peak","zh":"进入朝圣峰的上锁房间"},{"en":"Search the room for any construction research","zh":"在房间内搜寻建筑研究资料"},{"en":"Find the building pictured on the whiteboard","zh":"找到白板上描绘的建筑"},{"en":"Photograph the abandoned housing project","zh":"拍摄废弃的住宅工程"}],"rewards":[["power_rod",1]],"granted":[["blue_gate_communication_tower_key",1]],"prev":["deciphering_the_data"],"next":["worth_your_salt","a_dead_end"],"depth":25},{"id":"life_of_a_pharmacist","name":{"en":"Life of a Pharmacist","zh":"药剂师的生活"},"desc":{"en":"This place could use a makeover, but I don’t want it looking like your raggedy Raider Dens. See if you can find out how my fellow medical greats used to live.","zh":"这地方需要翻修一下，但我不想把它弄得跟你们那破破烂烂的奇袭者巢穴一样。你去了解一下我那些杰出的医疗同行以前的生活是怎样的。"},"trader":"Lance","maps":["buried_city"],"objectives":[{"en":"Find the Arbusto Farmacia by the collapsed highway","zh":"在崩塌的高速公路旁找到阿布斯托药店"},{"en":"Document the pharmacist’s hobbies","zh":"记录药剂师的爱好"},{"en":"Document the pharmacist’s family","zh":"记录药剂师的家人"},{"en":"Document the pharmacist’s taste","zh":"记录药剂师的品味"},{"en":"Document the pharmacist’s skills","zh":"记录药剂师的技能"}],"rewards":[["defibrillator",1],["surge_shield_recharger",1],["sterilized_bandage",3]],"prev":["espresso"],"next":["a_toxic_trail","tribute_to_toledo"],"depth":25},{"id":"a_dead_end","name":{"en":"A Dead End","zh":"死路一条"},"desc":{"en":"I… I don’t get it. One day they were trying to stave off the Collapse, and then, suddenly… Nothing.\n\nThat earthquake-resistant housing project was shut down by a group named MANTIKOR. Think you could find out more?","zh":"我……我不明白。前一天他们还在努力阻止“大崩溃”，然后，突然就……什么都没了。\n\n那个抗震住宅工程被一个叫螫蝎的组织叫停了。你能去查查更多线索吗？"},"trader":"Shani","maps":["the_blue_gate"],"objectives":[{"en":"Find MANTIKOR's underground facilities","zh":"找到螫蝎的地下设施"},{"en":"Find a way into into the locked room in the Security Wing","zh":"设法进入安保区辅楼的上锁房间"},{"en":"Search the locked room for any records on Project Heartwood","zh":"在上锁房间中搜寻关于“常青计划”的记录"},{"en":"Find the Dusty Film Reel","zh":"找到布满灰尘的电影胶卷"},{"en":"Deliver the Dusty Film Reel to Shani","zh":"将布满灰尘的电影胶卷交给萨尼"}],"oneRound":true,"required":[["dusty_film_reel",1]],"rewards":[["coins",2000]],"prev":["groundbreaking"],"next":["a_rising_tide","fragmented_logs"],"depth":26},{"id":"a_toxic_trail","name":{"en":"A Toxic Trail","zh":"有毒的踪迹"},"desc":{"en":"We've got clean water again, but we can't risk people falling ill if the saboteurs return. We need to root them out once and for all.","zh":"我们虽已恢复净水供应，但要是破坏者卷土重来，绝不能冒险让人染病。必须彻底铲除他们。"},"trader":"Shani","maps":["dam_battlegrounds"],"objectives":[{"en":"Return to the water intake below the Water Treatment Control building","zh":"返回水处理控制中心大楼下方的供水口"},{"en":"Search the swamp for traces of the barrel's origins","zh":"在沼泽中搜寻油桶来源的痕迹"},{"en":"Take a photo of the barrel truck","zh":"拍摄油桶卡车的照片"},{"en":"Search the truck for clues about the saboteur's identity","zh":"搜索卡车以寻找关于破坏者身份的线索"}],"rewards":[["tactical_mk2",1],["zipline",3],["pulse_mine",3],["gas_mine",3]],"prev":["life_of_a_pharmacist"],"next":["the_stench_of_corruption"],"depth":26},{"id":"tribute_to_toledo","name":{"en":"Tribute to Toledo","zh":"给托雷多管理层上贡"},"desc":{"en":"The Official Toledo Tubes Management is demanding one of our Power Rods for usage of “their” Slingshot tubes. Don’t let the name fool you, they’re in no way official; just thugs with lots of power. Could you help me with this?","zh":"托雷多暗道官方管理层要求我们提供一根能量管，以供他们使用“自己的”弹射管道。不要被他们的名字骗了，他们根本不是什么官方，只是一群手握大权的恶霸。能帮我解决这个问题吗？"},"trader":"Celeste","objectives":[{"en":"Get a Power Rod for Celeste","zh":"帮塞莱斯特找到一根能量管"}],"required":[["power_rod",1]],"rewards":[["magnet",5],["advanced_mechanical_components",2],["synthesized_fuel",3]],"prev":["life_of_a_pharmacist"],"next":["digging_up_dirt"],"depth":26},{"id":"worth_your_salt","name":{"en":"Worth Your Salt","zh":"电池的“盐”伸"},"desc":{"en":"I found notes that some electrical engineers at the Spaceport were working on advanced, salt-based batteries. If we can get our hands on one, perhaps it’ll prevent full-scale power outages next time a ceiling comes crashing down.","zh":"我发现有记录提到，太空港的一些电气工程师曾经一直在研究更先进的盐基电池。如果能弄到一个，也许下次天花板塌下来时就能避免大规模停电了。"},"trader":"Celeste","maps":["the_spaceport"],"objectives":[{"en":"Go to the Rocket Assembly","zh":"前往火箭组装区"},{"en":"Search for the hidden Battery Prototype in a high place","zh":"在高处搜寻隐藏的电池原型"},{"en":"Bring the Battery Prototype to the Industrial Recharger","zh":"把电池原型带到工业级充电器处"},{"en":"Use the machinery to charge the battery","zh":"使用充电器给电池充电"},{"en":"Deliver the Charged Battery to the drop-off point in the corner","zh":"将已充电的电池送到角落的投放点"}],"oneRound":true,"rewards":[["vita_spray_blueprint",1]],"prev":["groundbreaking"],"next":["on_deaf_ears"],"depth":26},{"id":"a_rising_tide","name":{"en":"A Rising Tide","zh":"涨潮"},"desc":{"en":"Says here there was a foreman at The Dam, who got recruited right after they canceled Project Heartwood. Got put in charge of some big reconstruction project.","zh":"记录上说，大坝那边有个工头，是在“常青计划”取消后招募的。负责某个大型重建项目。"},"trader":"Celeste","maps":["buried_city","dam_battlegrounds"],"objectives":[{"en":"On Buried City, find the foreman's barricaded apartment south of Piazza Roma","zh":"在掩埋废城的罗马广场南部找到设下障碍的工头公寓"},{"en":"Access the foreman's digital logbook","zh":"访问工头的数字日志"},{"en":"On Dam Battlegrounds, reach the Power Generation Complex","zh":"前往大坝战场的发电厂综合体"},{"en":"Find a way into the Controlled Access Zone","zh":"设法进入受控访问区"},{"en":"Search the Controlled Access Zone for any clues about the foreman's reconstruction project","zh":"在受控访问区搜寻关于工头重建项目的线索"}],"rewards":[["anvil_ii",1],["anvil_splitter",1],["extended_barrel_iii",1],["heavy_ammo",40]],"prev":["a_dead_end"],"depth":27},{"id":"digging_up_dirt","name":{"en":"Digging Up Dirt","zh":"揭露丑闻"},"desc":{"en":"We caught a break. One of our scouts saw a member of the Tubes Management make a dead drop inside the Santa Maria Houses in the Buried City. This might be our chance to dig up some dirt on them for a change. You in?","zh":"我们找到突破口了。一名侦察者看到暗道官方管理层的某位成员在掩埋废城的圣玛丽亚住宅区进行了一次秘密投放。这或许是个难得的机会，可以抓住他们的把柄。你参加吗？"},"trader":"Celeste","maps":["buried_city"],"objectives":[{"en":"Locate the Santa Maria Houses in Old Town","zh":"到老城区找到圣玛丽亚住宅区"},{"en":"Locate the Dead Drop inside the courtyard","zh":"在庭院内找到秘密投放点"}],"rewards":[["advanced_electrical_components",2],["speaker_component",4]],"prev":["tribute_to_toledo"],"next":["turnabout","building_a_library"],"depth":27},{"id":"fragmented_logs","name":{"en":"Fragmented Logs","zh":"碎片日志"},"desc":{"en":"Now that we’ve found our footing on Stella Montis, several parties are interested in digging a bit deeper and seeing what we can find out about the past of this place. To do so, however, we’ll need to power up some of these old machines so we can start to sift through the data.","zh":"我们在星辰山站稳脚跟后，多方势力都想深入挖掘此地的过往。但要做到这一点，我们得给这些老旧机械供电，才能梳理数据。"},"trader":"Shani","maps":["stella_montis"],"objectives":[{"en":"In either of the Robotic Sandbox control rooms, repair the out-of-service terminal with 1 Electrical Component","zh":"在机器人沙盘的任意控制室，使用1个电子元件修复故障终端"},{"en":"Enable the power in any of the conduit backrooms near the Robotic Sandboxes","zh":"接通机器人沙盘附近的任意管道后勤室的电源"},{"en":"Boot the main frame data terminal in the Cultural Archives service backrooms","zh":"启动文化档案馆后勤室的主机数据终端"}],"rewards":[["showstopper",3],["trailblazer",3]],"prev":["a_dead_end","dust_on_the_wires"],"next":["furtive_meetings"],"depth":27},{"id":"on_deaf_ears","name":{"en":"On Deaf Ears","zh":"充耳不闻"},"desc":{"en":"Seems like every other Raider here has some serious hearing damage.\n\nI heard rumors they developed some extra advanced hearing aids at Stella Montis. If you can track them down, we might all be able to use our indoor voices, for once.","zh":"这里的奇袭者似乎个个听力都有严重损伤。\n\n我听说星辰山那边研发了一些超先进的助听器。如果能找到，我们就能用正常音量说话了。"},"trader":"Lance","maps":["stella_montis"],"objectives":[{"en":"Find the researcher's guest logs on the reception computers","zh":"在接待处电脑上查找研究员的访客记录"},{"en":"Find where the researcher held their lecture, and access their notes","zh":"找到研究员举办讲座的地点，并查阅她的笔记"},{"en":"Find information about the prototypes on the Medical Research computers","zh":"在医学研究部电脑上查找原型的信息"},{"en":"Find the printed shipping logs in the Assembly Workshops","zh":"在组装厂车间里找到打印的货运日志"}],"rewards":[["lure_grenade",3],["noisemaker",5],["shaker",1]],"prev":["worth_your_salt","snap_and_salvage"],"next":["on_the_map"],"depth":27},{"id":"the_stench_of_corruption","name":{"en":"The Stench of Corruption","zh":"腐败的恶臭"},"desc":{"en":"That key you found in the barrel truck… I won’t jump to accusations just yet, but this certainly reeks of an inside job. Could you investigate a hunch I have?","zh":"你在油桶卡车里找到的钥匙……我暂时不妄下结论，但这明显是内部人员所为。能否帮忙验证一下我的直觉？"},"trader":"Shani","maps":["the_spaceport"],"objectives":[{"en":"Reach the southwest lobby of the Departure Building","zh":"抵达候机楼的西南大厅"},{"en":"Find the staff locker room","zh":"找到员工更衣室"},{"en":"Search the room for any clues of the saboteur's identity","zh":"在休息室内搜索关于破坏者身份的线索"},{"en":"Reach the tunnels below the Spaceport","zh":"到达太空港下方的隧道"},{"en":"Use the key on any Flushing Terminal to override the bypass protocol","zh":"在任意冲洗终端上使用钥匙覆盖旁路协议"}],"oneRound":true,"rewards":[["air_freshener",1],["dam_staff_room_key",1],["noisemaker",3]],"prev":["a_toxic_trail"],"depth":27},{"id":"building_a_library","name":{"en":"Building a Library","zh":"丰富图书室"},"desc":{"en":"Our library selection has grown pretty stale. Could you head out to Buried City, and find something more for us to read? Make sure you bring something for everyone.","zh":"我们的图书室藏书已经相当陈旧了。拜托你去掩埋废城找找，带点新书回来。记得多带点不同种类的。"},"trader":"Apollo","maps":["buried_city"],"objectives":[{"en":"Locate the Library in the City Center","zh":"在市中心找到图书馆"},{"en":"Find 1 romance book","zh":"找到1本言情小说"},{"en":"Find 1 detective book","zh":"找到1本侦探小说"},{"en":"Find 1 adventure book","zh":"找到1本冒险小说"},{"en":"Deliver 3 books to Apollo","zh":"将3本书交给阿波罗"}],"oneRound":true,"required":[["library_book",3]],"rewards":[["explosive_mine",1],["jolt_mine",1],["heavy_fuze_grenade",1]],"prev":["digging_up_dirt"],"next":["a_new_type_of_plant"],"depth":28},{"id":"furtive_meetings","name":{"en":"Furtive Meetings","zh":"秘密集会"},"desc":{"en":"I’m still sorting through the data you found in Stella Montis, but something’s caught my eye. I’d like you to look into it.","zh":"我还在整理你在星辰山找到的数据，但有件事引起了我的注意，我想让你去调查下。"},"trader":"Shani","maps":["stella_montis"],"objectives":[{"en":"Search for the secret meeting spot under a staircase in the Medical Research Area","zh":"在医学研究部区域的一处楼梯下方搜寻秘密集会地点"},{"en":"Find the secret meeting spot near the ventilation shaft between Robotic Sandbox B and Seed Vault","zh":"在机器人沙盘B区和种子库之间的通风井附近找到秘密集会地点"},{"en":"Find the secret meeting spot at the bottom of the staircase connecting the Cultural Archives and Seed Vault","zh":"在连接文化档案馆和种子库的楼梯底部找到秘密集会地点"},{"en":"Search the meeting area","zh":"搜查集会区域"},{"en":"Bring the Secret Meeting Info to Shani","zh":"将秘密集会情报交给萨尼"}],"oneRound":true,"required":[["secret_meeting_info",1]],"rewards":[["aphelion",1],["energy_clip",5]],"prev":["fragmented_logs"],"next":["last_entry"],"depth":28},{"id":"on_the_map","name":{"en":"On The Map","zh":"在地图上"},"desc":{"en":"We know the coordinates for those hearing aids, but I’ll have to cross-reference them with a paper map of the Spaceport. Those legs of yours aren’t too tired, are they?","zh":"我们知道那些助听器的坐标，但我得拿它跟太空港的纸质地图核对一下。你应该还没累到挪不动腿吧？"},"trader":"Lance","maps":["the_spaceport"],"objectives":[{"en":"Head to where the Fuel Lines snapped, and transmit your location","zh":"前往燃料管道断裂处，并发送你的位置"},{"en":"Head to the antenna near the Fuel Control, and transmit your location","zh":"前往燃料控制单元附近的天线处，并发送你的位置"},{"en":"Head to the cactus patch in the wall breach, and transmit your location","zh":"前往墙壁缺口处的仙人掌丛，并发送你的位置"},{"en":"Transmit your location from the roof of the Container Storage building","zh":"从集装箱仓库大楼屋顶发送你的位置"},{"en":"Find the container covered in tarp, and mark it","zh":"找到盖有防水布的容器，并标记它"}],"rewards":[["sterilized_bandage",3],["surge_shield_recharger",3],["tactical_mk3_healing",1]],"granted":[["defibrillator",3]],"prev":["on_deaf_ears"],"depth":28},{"id":"turnabout","name":{"en":"Turnabout","zh":"反将一军"},"desc":{"en":"I got a plan. If we recover the evidence against the OTTM before they get to it, we might get them off our backs once and for all.","zh":"我有个计划。如果能抢在OTTM之前找到对他们不利的证据，或许就能一劳永逸地摆脱他们的纠缠。"},"trader":"Celeste","maps":["the_spaceport"],"objectives":[{"en":"Go to the North Trench Tower","zh":"前往北壕沟塔"},{"en":"Find a spare key","zh":"找到一把备用钥匙"},{"en":"Locate and upload the blackmail files to Celeste","zh":"找到勒索文件并上传给塞莱斯特"}],"rewards":[["heavy_gun_parts",2],["medium_gun_parts",2]],"granted":[["spaceport_trench_tower_key",1]],"prev":["digging_up_dirt"],"depth":28},{"id":"a_new_type_of_plant","name":{"en":"A New Type of Plant","zh":"新型植物"},"desc":{"en":"Some scouts have been bringing back reports of these weird plants spreading into the area. Now, this makes your old pal Lance think it may have some interesting uses.","zh":"一些侦察者带回报告，说有些奇怪的植物正蔓延到本区域。你的老伙计兰斯听完就觉得，这种植物可能有些有趣的用途。"},"trader":"Lance","maps":["dam_battlegrounds"],"objectives":[{"en":"Search for the new plant near the Baron Husk in the Old Battleground","zh":"在旧战场的“男爵”残骸附近寻找新植物"},{"en":"Deliver the Possibly Toxic Plant to Lance","zh":"将可能有毒的植物交给兰斯"}],"oneRound":true,"required":[["possibly_toxic_plant",1]],"rewards":[["vita_shot",1],["antiseptic",5]],"prev":["building_a_library"],"next":["armored_transports"],"depth":29},{"id":"last_entry","name":{"en":"Last Entry","zh":"最后条目"},"desc":{"en":"More mentions of Mantikor, and more clear signs of dissent among the researchers. I suspect tensions eventually escalated.","zh":"文件中多次提及螫蝎，研究员之间的分歧也愈发明显。我怀疑矛盾最终激化了。"},"trader":"Shani","maps":["stella_montis"],"objectives":[{"en":"Find and access the right work station in the Seed Vault for clues","zh":"在种子库中找到并使用正确的工作站获取线索"},{"en":"Search for the hidden key in the adjacent room","zh":"在相邻房间搜寻隐藏钥匙"},{"en":"Search the Seed Vault and unlock the seed deposit box","zh":"搜索种子库并解锁种子存放箱"},{"en":"Search the seed deposit box","zh":"搜索种子存放箱"},{"en":"Bring the Official Shutdown Documentation to Shani","zh":"将官方关停文件交给萨尼"}],"oneRound":true,"required":[["official_shutdown_documentation",1]],"rewards":[["yellow_light_stick_blueprint",1]],"prev":["furtive_meetings"],"next":["line_in_the_sand"],"depth":29},{"id":"armored_transports","name":{"en":"Armored Transports","zh":"装甲运输"},"desc":{"en":"Ever since we expanded the tunnels to the Blue Gate, some rare pieces have started appearing on the black market.\n\nMeanwhile, I'm stuck here peddling battered old Rattlers. If I don't find new supply lines, I'll be left in the dust.","zh":"自从我们将地道扩展到蓝门以来，黑市上开始出现一些稀有零件。与此同时，我却困在这里兜售老掉牙的“响尾蛇”。如果不找到新的供应线，我就要被市场淘汰了。"},"trader":"Tian Wen","maps":["the_blue_gate"],"objectives":[{"en":"Reach the Checkpoint","zh":"抵达检查站"},{"en":"Search the Guard huts for an Armored Patrol Key Card","zh":"在警卫室搜索装甲巡逻车钥匙卡"},{"en":"Reach the Traffic Tunnel near the Blue Gate Checkpoint","zh":"抵达蓝门检查站附近的通行隧道"},{"en":"Find a spare Armored Patrol Car Key Card","zh":"找到备用的装甲巡逻车钥匙卡"},{"en":"Find and unlock the rear door of an armored patrol car","zh":"找到并解锁装甲巡逻车的后门"}],"rewards":[["smoke_grenade",3],["defibrillator",3]],"prev":["with_a_trace","a_new_type_of_plant"],"depth":30},{"id":"line_in_the_sand","name":{"en":"Line in the Sand","zh":"沙滩防线"},"desc":{"en":"That Stella Montis hard drive contained more than just the shutdown documentation - it also had the transport schedules of some pretty critical Exodus components.","zh":"那个星辰山硬盘里不光有关停文件，还有“离巢”关键部件的运输时刻表。"},"trader":"Celeste","maps":["buried_city"],"objectives":[{"en":"Find out why the train never reached Marano Station","zh":"查明列车为何未能抵达马拉诺车站"},{"en":"Find out who orchestrated the robbery","zh":"查明策划劫案的主谋"},{"en":"Find out where the thruster valves were stashed","zh":"查明推进器阀门的藏匿地点"},{"en":"Search the basement of the merchant’s nearby apartment","zh":"搜查附近商人公寓的地下室"}],"rewards":[["exodus_modules",2],["magnetic_accelerator",2],["magnetron",2]],"prev":["last_entry"],"next":["safe_harbor"],"depth":30},{"id":"safe_harbor","name":{"en":"Safe Harbor","zh":"安全港湾"},"desc":{"en":"Seems like news of the train derailment spread fast… And drove many workers to stash some very tasty technology away from prying eyes.","zh":"列车脱轨的消息传得真快……还促使不少工人把值钱的科技装备藏了起来，避开耳目。"},"trader":"Tian Wen","maps":["riven_tides"],"objectives":[{"en":"Find the clue left by the restaurant kitchen staff","zh":"找到餐厅后厨员工留下的线索"},{"en":"Find the area portrayed in the sketch","zh":"找到素描中描绘的区域"},{"en":"Dig up the buried part","zh":"挖出掩埋的零件"},{"en":"Deliver the Precision Gimbal to Tian Wen","zh":"将精密云台交给天玟"}],"oneRound":true,"required":[["precision_gimbal",1]],"rewards":[["surge_coil",1],["heavy_gun_parts",1],["horizontal_grip",1]],"prev":["line_in_the_sand"],"next":["a_wrench_in_the_works"],"depth":31},{"id":"a_wrench_in_the_works","name":{"en":"A Wrench in the Works","zh":"暗中破坏"},"desc":{"en":"Looks like the resentment ended up reaching the ground staff of the Spaceport itself. A mutiny brewing, right in the heart of the Exodus.","zh":"看来不满情绪蔓延到了太空港的地勤员工，“离巢”的核心地带正在酝酿叛乱。"},"trader":"Celeste","maps":["the_spaceport"],"objectives":[{"en":"Search the buses near the western gate","zh":"搜索西门附近的巴士"},{"en":"Locate the stash of sabotage supplies hidden at the Water Towers","zh":"找到藏在水塔的破坏物资储备箱"}],"rewards":[["mechanical_components",5],["mod_components",3]],"prev":["safe_harbor"],"depth":32}];
